import { describe, expect, it } from 'vitest';
import { revisionFixture } from '../../../../tests/support/diagramRevisions';
import { connectionContentNodes, defaultArrowAppearance, reconcileConnections, type ContentNodeAnchor, type DiagramConnection } from '../../../core/diagrams/diagramConnection';
import { singleDiagramScene } from '../../../core/diagrams/projectDiagramCanvas';
import { MappingDocumentController, type DiagramOperation } from '../mappingDocumentController';
import { mappingDocumentFromScene } from '../mappingDocument';
import { initialCanvasState } from '../mappingWorkspace';
import { deserializeWorkspace, serializeWorkspace } from '../mappingWorkspaceCodec';
import { drawEdge } from '../connectionLayout';

function setup() {
  const scene = singleDiagramScene('Root\n+-- Branch\n|   `-- Leaf\n`-- Leaf');
  scene.contents = { ...scene.contents, overview: revisionFixture().create({ id: 'overview', revision: 0, ascii: scene.contents.overview.content.ascii, structureKind: 'tree' }).diagram };
  if (scene.root.kind === 'container') scene.root.children = [...scene.root.children, {
    id: 'second', kind: 'diagram', contentId: 'overview', position: { column: 40, row: 2 }, collapsed: false
  }];
  const controller = new MappingDocumentController(mappingDocumentFromScene(scene), initialCanvasState());
  const source = (line = 3, displayNodeId = 'grid:overview'): ContentNodeAnchor => {
    const content = controller.getSnapshot().document.scene.contents.overview.content;
    return { kind: 'content-node', displayNodeId, contentNodeId: connectionContentNodes(content).find(node => node.line === line)!.id, revisionId: content.revisionId, side: 'right' };
  };
  const edge: DiagramConnection = { id: 'link', source: source(), target: { kind: 'box', displayNodeId: 'grid:second', side: 'left' }, appearance: { ...defaultArrowAppearance } };
  const apply = (...ops: DiagramOperation[]) => controller.transact(controller.getSnapshot().version, ops);
  const geometry = () => { const s = controller.getSnapshot(); return drawEdge(s.document.edges[0], s.document.scene, s.canvas.diagramViews, { width: 8, height: 18 }); };
  return { controller, source, edge, apply, geometry };
}

describe('document connections', () => {
  it('does not revive an already-stale endpoint using correspondence for the current revision', () => {
    const { controller, edge } = setup();
    const before = controller.getSnapshot().document.scene;
    const base = before.contents.overview;
    const next = revisionFixture().revise(base.revisionId, { kind: 'patch', start: 4, end: 4, patch: '`-- New leaf' });
    const after = { ...before, contents: { ...before.contents, overview: next.diagram } };
    const stale = { ...edge, source: { ...edge.source, revisionId: 'older-content-revision' } };
    expect(next.nodeIds.has(edge.source.contentNodeId)).toBe(true);
    expect(reconcileConnections(before, after, [stale], next.nodeIds)).toEqual([stale]);
  });
  it('creates an independent relationship and derived FloatingBoxArrow without changing any diagram or panel', () => {
    const { controller, edge, apply } = setup();
    const before = structuredClone(controller.getSnapshot());
    apply({ method: 'edge-create', edge });
    expect(controller.getSnapshot().document.scene).toEqual(before.document.scene);
    expect(controller.getSnapshot().canvas).toEqual(before.canvas);
    expect(controller.nodes().find(node => node.id === 'floating:edge:link')).toMatchObject({ layout: 'floating', kind: 'arrow', collapsible: { self: false }, value: { edgeId: 'link', status: 'resolved' } });
    expect(controller.getSnapshot().canvas.display.nodes).toEqual({});
    controller.undo(); expect(controller.getSnapshot().document.edges).toEqual([]);
    controller.undo(true); expect(controller.getSnapshot().document.edges).toEqual([edge]);
    apply({ method: 'remove', nodeId: 'floating:edge:link' });
    expect(controller.getSnapshot().document.scene).toEqual(before.document.scene);
  });
  it('anchors duplicate labels and repeated diagram instances independently; follows moves in canvas pixels', () => {
    const { controller, source, edge, apply, geometry } = setup();
    edge.target = { ...source(4, 'grid:second'), side: 'left' };
    apply({ method: 'edge-create', edge });
    const before = geometry();
    expect(before.source).toMatchObject({ x: 96, y: 45, side: 'right', proxy: false });
    expect(before.target).toMatchObject({ x: 352, y: 99, side: 'left' });
    apply({ method: 'move', nodeId: 'grid:second', position: { column: 50, row: 5 } });
    expect(geometry().source).toEqual(before.source);
    expect(geometry().target!.x).toBe(before.target!.x + 80);
    expect(geometry().target!.y).toBe(before.target!.y + 54);
    expect(controller.getSnapshot().document.edges[0]).toEqual(edge);
  });
  it('projects folded nodes to visible ancestors and restores the precise attachment on expansion', () => {
    const { controller, source, edge, apply, geometry } = setup();
    apply({ method: 'edge-create', edge });
    const before = geometry();
    apply({ method: 'collapse', nodeId: 'grid:overview', contentNodeId: source(2).contentNodeId, collapsed: true });
    expect(geometry()).toMatchObject({ status: 'proxy', source: { y: 27, proxy: true } });
    expect(controller.getSnapshot().document.edges[0]).toEqual(edge);
    controller.undo(); expect(geometry()).toEqual(before);
    apply({ method: 'collapse', nodeId: 'grid:overview', collapsed: true });
    expect(geometry().status).toBe('proxy');
  });
  it('follows an enclosing collapsed GridBox and prunes incident edges when the group is deleted', () => {
    const { controller, edge, apply, geometry } = setup();
    const doc = structuredClone(controller.getSnapshot().document);
    if (doc.scene.root.kind !== 'container') throw new Error();
    const second = doc.scene.root.children[1];
    doc.scene.root.children = [doc.scene.root.children[0], { id: 'group', kind: 'container', position: { column: 40, row: 2 }, collapsed: false,
      collapsedContentId: 'overview-summary', layout: { collisionPolicy: 'push-right', gap: 3 }, children: [{ ...second, position: { column: 0, row: 0 } }] }];
    controller.commitDocument(doc);
    apply({ method: 'edge-create', edge }, { method: 'collapse', nodeId: 'grid:group', collapsed: true });
    expect(geometry()).toMatchObject({ status: 'proxy', target: { proxy: true, x: 320 } });
    apply({ method: 'remove', nodeId: 'grid:group' });
    expect(controller.getSnapshot().document.edges).toEqual([]);
    controller.undo(); expect(controller.getSnapshot().document.edges).toEqual([edge]);
  });
  it('preserves revision identity on unchanged text; changed text is stale until explicitly reattached', () => {
    const { controller, source, edge, apply, geometry } = setup();
    apply({ method: 'edge-create', edge });
    apply({ method: 'replace', nodeId: 'grid:overview', ascii: controller.getSnapshot().document.scene.contents.overview.content.ascii });
    expect(geometry().status).toBe('resolved');
    expect(controller.getSnapshot().document.edges[0].source.revisionId).not.toBe(edge.source.revisionId);
    apply({ method: 'replace', nodeId: 'grid:overview', ascii: 'Root\n+-- Changed\n|   `-- Leaf\n`-- Leaf' });
    expect(geometry().status).toBe('stale');
    const stale = controller.getSnapshot().document.edges[0];
    apply({ method: 'edge-update', edge: { ...stale, appearance: { ...stale.appearance, label: 'Needs repair' } } });
    expect(geometry().status).toBe('stale');
    apply({ method: 'edge-update', edge: { ...stale, source: source() } });
    expect(geometry().status).toBe('resolved');
  });
  it('validates endpoint kinds and revisions; rejects malformed or stale transactions atomically', () => {
    const { controller, edge, apply } = setup();
    const before = controller.getSnapshot();
    expect(() => apply({ method: 'edge-create', edge }, { method: 'edge-create', edge })).toThrow('already exists');
    expect(controller.getSnapshot()).toBe(before);
    expect(() => apply({ method: 'edge-create', edge: { ...edge, source: { ...edge.source, revisionId: 'old' } } })).toThrow('STALE');
    expect(() => apply({ method: 'edge-create', edge: { ...edge, target: { ...edge.target, displayNodeId: 'floating:missing' } } })).toThrow('GridBox');
    expect(() => apply({ method: 'edge-create', edge: { ...edge, source: edge.target as ContentNodeAnchor } })).toThrow();
    apply({ method: 'edge-create', edge });
    expect(() => controller.transact(before.version, [{ method: 'edge-remove', edgeId: edge.id }])).toThrow('VERSION_CONFLICT');
  });
  it('does not revive deleted attachments when a GridBox ID is reused in the same transaction', () => {
    const { controller, edge, apply } = setup();
    apply({ method: 'edge-create', edge });
    apply({ method: 'remove', nodeId: 'grid:second' }, { method: 'diagram-create', id: 'second', ascii: 'New diagram' });
    expect(controller.getSnapshot().document.edges).toEqual([]);
    controller.undo(); expect(controller.getSnapshot().document.edges).toEqual([edge]);
  });
  it('indexes graph labels without converting or editing the diagram', () => {
    const content = revisionFixture().create({ id: 'graph', revision: 0, ascii: '[Alpha] ---> [Beta]', structureKind: 'diagram' }).diagram.content;
    const before = structuredClone(content);
    expect(connectionContentNodes(content).map(node => node.label)).toEqual(['[Alpha]', '[Beta]']);
    expect(content).toEqual(before);
  });
  it('round-trips saved and unsaved edges and migrates old workspaces to an empty edge array', () => {
    const { controller, edge, apply } = setup();
    apply({ method: 'edge-create', edge });
    const { document, canvas } = controller.getSnapshot();
    const workspace = { schemaVersion: 3 as const, projectId: 'project', documents: [{ representationId: 'diagram', revisionId: 'revision', name: 'Test', savedName: 'Test',
      savedScene: JSON.stringify(document.scene), savedEdges: '[]', document, canvas }] };
    expect(deserializeWorkspace(serializeWorkspace(workspace))).toEqual(workspace);
    const old: any = structuredClone(workspace); delete old.documents[0].document.edges; delete old.documents[0].savedEdges;
    expect(deserializeWorkspace(old).documents[0].document.edges).toEqual([]);
    old.documents[0].document.edges = [edge, edge];
    expect(() => deserializeWorkspace(old)).toThrow('Duplicate connection');
  });
});

import { mutableFixture } from '../../../../tests/support/mappingDiagram';
import { expect, it } from 'vitest';
import { revisionFixture } from '../../../../tests/support/diagramRevisions';
import { buildDiagramContent } from '../../../core/diagrams/diagramContent';
import { activeDiagramJumps, validateDiagramJumps, type DiagramJump } from '../../../core/diagrams/diagramJump';
import { singleDiagramScene } from '../../../core/diagrams/projectDiagramCanvas';
import { diagramSceneText } from '../diagramSceneText';
import { MappingDocumentController } from '../mappingDocumentController';
import { mappingDocumentFromScene } from '../mappingDocument';
import { initialCanvasState } from '../mappingWorkspace';
import { serializeWorkspace, deserializeWorkspace } from '../mappingWorkspaceCodec';

function fixture() {
  const ascii = 'Root\n|-- [*] Rendering\nplain text';
  const scene = singleDiagramScene(ascii);
  scene.contents = { ...scene.contents, overview: revisionFixture().create({ id: 'overview', revision: 0, ascii, structureKind: 'tree' }).diagram };
  const content = scene.contents.overview.content;
  const jump: DiagramJump = { id: 'rendering', source: { revisionId: content.revisionId, contentHash: content.asciiSha256,
    line: 2, startColumn: 5, endColumn: 17 }, target: { representationId: 'saved-target', displayNodeId: 'grid:overview' } };
  const controller = new MappingDocumentController(mappingDocumentFromScene(scene), initialCanvasState());
  return { scene, content, jump, controller, ascii };
}

it('adds coordinate-fallback jumps without changing text, with undo/redo and workspace round trips', () => {
  const { controller, jump, ascii } = fixture();
  controller.transact(0, [{ method: 'setJumps', nodeId: 'grid:overview', jumps: [jump] }]);
  const { document, canvas } = controller.getSnapshot();
  expect(document.scene.contents.overview.content.ascii).toBe(ascii);
  expect(diagramSceneText(document.scene).rows.flatMap(row => row.runs).find(run => run.jump)?.text).toBe('[*] Rendering');
  const workspace = { schemaVersion: 3 as const, projectId: 'project', documents: [{ representationId: 'source', name: 'Source',
    savedName: 'Source', revisionId: 'revision', savedScene: JSON.stringify(document.scene), document, canvas }] };
  expect(deserializeWorkspace(serializeWorkspace(workspace)).documents[0].document.scene.contents.overview.jumps).toEqual([jump]);
  controller.undo(); expect(controller.getSnapshot().document.scene.contents.overview.jumps).toBeUndefined();
  controller.undo(true); expect(controller.getSnapshot().document.scene.contents.overview.jumps).toEqual([jump]);
});

it('rebases unchanged text and disables stale links after replacement, without losing the metadata', () => {
  const { controller, jump, ascii } = fixture();
  controller.transact(0, [{ method: 'setJumps', nodeId: 'grid:overview', jumps: [jump] }]);
  controller.transact(1, [{ method: 'replace', nodeId: 'grid:overview', ascii }]);
  let diagram = controller.getSnapshot().document.scene.contents.overview;
  expect(activeDiagramJumps(diagram.content, diagram.jumps)).toHaveLength(1);
  expect(diagram.jumps![0].source.revisionId).toBe('overview:1');
  controller.transact(2, [{ method: 'replace', nodeId: 'grid:overview', ascii: ascii.replace('Rendering', 'Different') }]);
  diagram = controller.getSnapshot().document.scene.contents.overview;
  expect(diagram.jumps).toHaveLength(1);
  expect(activeDiagramJumps(diagram.content, diagram.jumps)).toEqual([]);
});

it('rejects stale source ranges, invalid node IDs and overlapping links atomically', () => {
  const { controller, jump, content } = fixture();
  expect(() => validateDiagramJumps(content, [{ ...jump, source: { ...jump.source, contentNodeId: 'fake' } }], false)).toThrow('STALE_CONTENT_NODE');
  expect(() => validateDiagramJumps(content, [{ ...jump, source: { ...jump.source, revisionId: 'old' } }], false)).toThrow('STALE_JUMP_SOURCE');
  expect(() => controller.transact(0, [{ method: 'setJumps', nodeId: 'grid:overview', jumps: [jump, { ...jump, id: 'another' }] }])).toThrow('Overlapping');
  expect(controller.getSnapshot().version).toBe(0);
});

it('restores legacy parsed structures exactly instead of upgrading their grammar on workspace load', () => {
  const { controller } = fixture();
  const { document, canvas } = structuredClone(controller.getSnapshot());
  const diagram = mutableFixture(document.scene.contents.overview);
  document.scene.contents = { ...document.scene.contents, overview: diagram };
  diagram.content = mutableFixture( buildDiagramContent(diagram.content.ascii, diagram.content.revisionId, 'tree', 'ascii-tree-1'));
  const workspace = { schemaVersion: 3 as const, projectId: 'project', documents: [{ representationId: 'source', name: 'Source',
    savedName: 'Source', revisionId: 'revision', savedScene: JSON.stringify(document.scene), document, canvas }] };
  const restored = deserializeWorkspace(serializeWorkspace(workspace));
  expect(restored.documents[0].document.scene.contents.overview.content).toEqual(diagram.content);
});

import { revisionFixture } from '../../../../tests/support/diagramRevisions';
import { describe, expect, it } from 'vitest';
import { singleDiagramScene } from '../../../core/diagrams/projectDiagramCanvas';
import { composeScene, resolveScene, flattenGrid } from '../../../core/diagrams/lineGrid';
import { diagramProjection, resolveDiagramView } from '../diagramViewState';
import { MappingDocumentController } from '../mappingDocumentController';
import { mappingDocumentFromScene } from '../mappingDocument';
import { initialCanvasState } from '../mappingWorkspace';
import { deserializeWorkspace, serializeWorkspace } from '../mappingWorkspaceCodec';
import { displayGeometry } from '../displayModel';
import { layoutFloatingSelections } from '../floatingBoxLayout';

const ascii = 'Content\n+-- structure\n|   +-- tree\n|   |   `-- nodes\n|   `-- diagram\n`-- footer';
const setup = () => {
  const scene = singleDiagramScene(ascii);
  scene.contents = {...scene.contents, overview: revisionFixture().create({id:'overview',revision:0,ascii:scene.contents.overview.content.ascii,structureKind:'tree'}).diagram};
  return new MappingDocumentController(mappingDocumentFromScene(scene), initialCanvasState());
};
const target = (controller: MappingDocumentController, line: number) => controller.nodes().find(n => n.id === 'grid:overview')!.collapsible.subtrees.find(t => t.line === line)!;
const collapse = (controller: MappingDocumentController, line: number, collapsed = true) => controller.transact(controller.getSnapshot().version, [{method:'collapse',nodeId:'grid:overview',contentNodeId:target(controller,line).contentNodeId,collapsed}]);
const projection = (controller: MappingDocumentController) => {
  const {document,canvas} = controller.getSnapshot();
  return diagramProjection(document.scene,'overview','overview',canvas.diagramViews);
};
describe('diagram subtree view state', () => {
  it('preserves source layout while reducing displayed bounds with nested folds', () => {
    const c = setup(), before = c.getSnapshot().document;
    const bounds = () => {
      const node = c.nodes().find(n => n.id === 'grid:overview')!;
      if (node.layout !== 'grid') throw Error('Expected diagram');
      return node.geometry.bounds;
    };
    const initial = bounds();
    collapse(c,3); collapse(c,2);
    expect(projection(c).sourceLines).toEqual([1,2,6]);
    expect(bounds()).toEqual({ ...initial, columns: 13, rows: 3 });
    expect(target(c,3)).toMatchObject({expansion:'collapsed',visibleRow:undefined});
    collapse(c,2,false);
    expect(projection(c).sourceLines).toEqual([1,2,3,5,6]);
    expect(bounds()).toEqual({ ...initial, columns: 15, rows: 5 });
    expect(projection(c).rowForLine(6)).toBe(4);
    expect(projection(c).lineForRow(4)).toBe(6);
    expect(projection(c).rect({startLine:3,endLine:5,startColumn:1,endColumn:4})).toBeUndefined();
    const {document,canvas}=c.getSnapshot();
    expect(document).toEqual(before);
    const rendered=composeScene(document.scene,(content,box)=>diagramProjection(document.scene,box.id,content.id,canvas.diagramViews).ascii);
    expect(rendered.split('\n').length).toBe(ascii.split('\n').length);
    expect(rendered).not.toContain('nodes');
    expect(resolveScene(document.scene)).toEqual(resolveScene(before.scene));
    c.undo(); expect(projection(c).sourceLines).toEqual([1,2,6]); expect(bounds().rows).toBe(3);
    c.undo(true); expect(projection(c).sourceLines).toEqual([1,2,3,5,6]); expect(bounds().rows).toBe(5);
    collapse(c,3,false); expect(bounds()).toEqual(initial);
  });
  it('shrinks containing groups and retains reserved extra space without moving siblings', () => {
    const c = setup();
    c.transact(0, [{ method: 'group', nodeId: 'grid:overview', id: 'group' },
      { method: 'diagram-create', id: 'sibling', ascii: 'Sibling', position: { column: 60, row: 0 } }]);
    const state = c.getSnapshot();
    const scene = structuredClone(state.document.scene);
    const diagram = flattenGrid(resolveScene(scene)).find(n => n.box.id === 'overview')!;
    diagram.box.minimumSize = { columns: diagram.bounds.columns + 5, rows: diagram.bounds.rows + 2 };
    c.commitDocument({ ...state.document, scene });
    const expanded = flattenGrid(resolveDiagramView(scene));
    collapse(c,2);
    const folded = flattenGrid(resolveDiagramView(scene, c.getSnapshot().canvas.diagramViews));
    expect(folded.find(n => n.box.id === 'overview')!.bounds).toMatchObject({ columns: 18, rows: 5 });
    expect(folded.find(n => n.box.id === 'group')!.bounds).toMatchObject({ columns: 18, rows: 5 });
    expect(folded.find(n => n.box.id === 'sibling')!.bounds).toEqual(expanded.find(n => n.box.id === 'sibling')!.bounds);
  });
  it('rejects stale, leaf, and wrong-owner targets atomically; resets view state on source replacement and restores it on undo', () => {
    const c=setup(); collapse(c,2);
    const state=c.getSnapshot(), id=target(c,2).contentNodeId;
    expect(()=>c.transact(state.version,[{method:'collapse',nodeId:'grid:root',contentNodeId:id,collapsed:true}])).toThrow('diagram DisplayNode');
    expect(()=>c.transact(state.version,[{method:'collapse',nodeId:'grid:overview',contentNodeId:'old-revision',collapsed:true}])).toThrow('STALE_CONTENT_NODE');
    expect(()=>c.transact(state.version,[{method:'collapse',nodeId:'grid:overview',contentNodeId:id.replace('line-2','line-4'),collapsed:true}])).toThrow('no children');
    expect(c.getSnapshot()).toBe(state);
    c.transact(state.version,[{method:'replace',nodeId:'grid:overview',ascii:'New\n`-- child',structureKind:'tree'}]);
    expect(c.getSnapshot().canvas.diagramViews).toEqual({});
    c.undo(); expect(projection(c).sourceLines).toEqual([1,2,6]);
  });
  it('round-trips workspace state, accepts older workspaces and rejects invalid saved targets', () => {
    const c=setup();collapse(c,2);const s=c.getSnapshot();
    const workspace={schemaVersion:3 as const,projectId:'project',documents:[{representationId:'diagram',revisionId:'revision',name:'Test',savedName:'Test',savedScene:JSON.stringify(s.document.scene),document:s.document,canvas:s.canvas}]};
    expect(deserializeWorkspace(serializeWorkspace(workspace)).documents[0].canvas.diagramViews).toEqual(s.canvas.diagramViews);
    const old=structuredClone(workspace);delete old.documents[0].canvas.diagramViews;
    expect(deserializeWorkspace(old).documents[0].canvas.diagramViews).toBeUndefined();
    const bad=structuredClone(workspace);bad.documents[0].canvas.diagramViews!['grid:overview'].collapsedContentNodeIds.push('missing');
    expect(()=>deserializeWorkspace(bad)).toThrow('stale diagram view');
  });
  it('keeps two instances independent and prunes a removed owner', () => {
    const c=setup(),s=c.getSnapshot();
    if(s.document.scene.root.kind!=='container') throw new Error('fixture');
    c.commitDocument({...s.document,scene:{...s.document.scene,root:{...s.document.scene.root,children:[...s.document.scene.root.children,{id:'copy',kind:'diagram',contentId:'overview',position:{column:40,row:0},collapsed:false}]}}});
    collapse(c,2);
    expect(c.nodes().find(n=>n.id==='grid:copy')!.collapsible.subtrees.every(t=>t.expansion==='expanded')).toBe(true);
    c.transact(c.getSnapshot().version,[{method:'remove',nodeId:'grid:overview'}]);
    expect(c.getSnapshot().canvas.diagramViews).toEqual({});
  });
  it('moves a retained source attachment to its visible row without changing its source rectangle', () => {
    const c=setup();collapse(c,2);const {document,canvas}=c.getSnapshot();
    const rect={startLine:6,endLine:6,startColumn:1,endColumn:5};
    const state={rootIds:['selection'],nodes:{selection:{...displayGeometry(),id:'selection',kind:'selection' as const,childIds:[],expansion:'expanded' as const,sourceBoxId:'overview',sourceContentId:'overview',sourceAscii:ascii,rect,selectedIds:[],displayMode:'stacked' as const}}};
    const result=layoutFloatingSelections(state,flattenGrid(resolveScene(document.scene)),document.scene,{width:8,height:18},canvas.diagramViews);
    expect(result.nodes.selection.position).toEqual({x:0,y:36});
    expect(result.nodes.selection).toMatchObject({rect});
  });
});

