import { expect, it } from 'vitest';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { CanvasCatalogStore } from '../canvasCatalogStore';
import { WorkspaceRecordStore } from '../../../mapping/persistence/workspace/workspaceRecordStore';
import { documentPrefix, historyChanges } from '../../../../domain/mapping/workspace/workspaceRecords';
import { MappingDocumentController } from '../../../../domain/mapping/workspace/mappingDocumentController';
import { mappingDocumentFromScene } from '../../../../domain/mapping/workspace/mappingDocument';
import { initialCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';
import { singleDiagramScene, historyFromRevision } from '../../../../domain/core/diagrams/projectDiagramCanvas';

it('publishes persisted records without expanding a >100 MiB archive, preserves it on restore, and deduplicates receipts', async () => {
  const root = await mkdtemp(join(tmpdir(), 'checkpoint-publication-'));
  try {
    const controller = new MappingDocumentController(mappingDocumentFromScene(singleDiagramScene('Service')), initialCanvasState());
    controller.applyUpdate(0, [{ method: 'highlight', nodeId: 'grid:overview', color: 'blue', highlightId: 'h' }]);
    const delta = controller.persistenceChanges();
    // Historical presentation data can dwarf the current document. Store it once.
    delta.snapshots = structuredClone(delta.snapshots);
    delta.snapshots[delta.header.baselineId].view = { archive: 'x'.repeat(101 * 1024 * 1024) };
    delete delta.storage; // Re-encode the deliberately changed test archive.
    const workspace = new WorkspaceRecordStore(root);
    await workspace.state('project', async () => null);
    const prefix = documentPrefix('draft-doc');
    await workspace.apply('project', { requestId: 'persist', expectedRevision: 0, changes: [
      { key: 'workspace', value: { projectId: 'project', documentIds: ['draft-doc'], activeDocumentId: 'draft-doc', transfers: [] } },
      ...historyChanges('draft-doc', delta),
      { key: prefix + 'metadata', value: { representationId: 'draft-doc', name: 'Test', version: 1 } },
      { key: prefix + 'baseline', value: { revisionId: '', savedName: '', savedScene: JSON.stringify(controller.getSnapshot().document.scene), savedEdges: '[]' } },
      { key: prefix + 'canvas', value: controller.getSnapshot().canvas }
    ] });
    const catalog = new CanvasCatalogStore(root);
    const input = { documentId: 'draft-doc', checkpointId: delta.header.headId, expectedVersion: 1, requestId: 'publish', name: 'Saved' };
    const receipt = await catalog.publishCheckpoint('project', input, () => workspace.capture('project', input.documentId, input.checkpointId, input.expectedVersion));
    expect(Buffer.byteLength(JSON.stringify(receipt))).toBeLessThan(2000);
    expect(await catalog.publishCheckpoint('project', input, () => workspace.capture('project', input.documentId, input.checkpointId, input.expectedVersion))).toEqual(receipt);
    await expect(catalog.publishCheckpoint('project', { ...input, name: 'Different' }, async () => { throw Error('must not capture'); })).rejects.toThrow('REQUEST_ID_CONFLICT');
    await expect(catalog.publishCheckpoint('project', { ...input, requestId: 'stale', expectedVersion: 0 }, () => workspace.capture('project', input.documentId, input.checkpointId, 0))).rejects.toThrow('VERSION_CONFLICT');
    const stored = await readFile(join(root, 'canvases/catalog.json'), 'utf8');
    expect(Buffer.byteLength(stored)).toBeLessThan(30_000);
    expect(stored).toContain('workspaceRecords');
    const manifest = JSON.parse(await readFile(join(root, 'workspace-records.json'), 'utf8'));
    const archived = manifest.records[prefix + 'checkpoint/' + delta.header.baselineId];
    // A current read must not open an unrelated archived checkpoint.
    const archivePath = join(root, 'workspace-records', archived + '.json');
    const archivedText = await readFile(archivePath, 'utf8');
    await writeFile(archivePath, 'unreadable archive');
    const current = await catalog.loadCurrentRepresentationCatalog('project');
    const history = historyFromRevision(current.revisions[receipt.revisionId]);
    expect(Object.keys(history.snapshots)).toEqual([delta.header.headId]);
    expect(history.snapshots[history.headId].document.diagramPresentations?.overview.highlights).toHaveLength(1);
    // Save references still pin the exact archived record; restore the fixture and verify full-history readers.
    await writeFile(archivePath, archivedText);
    const restored = await catalog.loadRepresentationCatalog('project');
    const full = historyFromRevision(restored.revisions[receipt.revisionId]);
    expect((full.snapshots[full.baselineId].view as { archive: string }).archive.length).toBe(101 * 1024 * 1024);
    expect(full.past).toEqual(delta.header.past);
  } finally { await rm(root, { recursive: true, force: true }); }
}, 30_000);

import { afterEach, expect, it } from 'vitest';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { IdentityMigration, prepareMigration, publishMigration, verifyMigration } from '../../../../scripts/migrations/migrate-diagram-identities';
import { CanvasHistory, documentFromHistory, validateCanvasHistory } from '../../../../domain/core/diagrams/canvasHistory';
import { singleDiagramScene } from '../../../../domain/core/diagrams/projectDiagramCanvas';
import { revisionFixture } from '../../../../tests/support/diagramRevisions';
import { initialCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';
import { CanvasCatalogStore } from '../canvasCatalogStore';

function oldHistory() {
  const service = revisionFixture();
  const document = { scene: singleDiagramScene('Before'), edges: [], sections: {} };
  const h = new CanvasHistory(document, initialCanvasState());
  const next = service.revise(document.scene.contents.overview.revisionId, { kind: 'replace', input: { ascii: 'After' } });
  h.append({ ...document, scene: { ...document.scene, contents: { ...document.scene.contents, overview: next.diagram } } }, initialCanvasState());
  h.navigate(); // Retain redo as well as both immutable revisions.
  const raw: any = h.export();
  const ids = Object.fromEntries(Object.keys(raw.diagramRevisions).map(id => [id, `diagram-revision-${crypto.randomUUID()}`]));
  raw.diagramRevisions = Object.fromEntries(Object.values(raw.diagramRevisions).map((r: any) => {
    r.id = ids[r.id]; if (r.parentId) r.parentId = ids[r.parentId];
    r.diagramId = r.diagram.id; delete r.diagram.diagramId; delete r.diagram.revisionId;
    return [r.id, r];
  }));
  for (const s of Object.values(raw.snapshots) as any[]) for (const k of Object.keys(s.diagramBindings)) s.diagramBindings[k] = ids[s.diagramBindings[k]];
  return raw;
}

it('preserves revision ancestry, node references, checkpoints and redo while assigning lineage identities', () => {
  const old = oldHistory(), migration = new IdentityMigration(); migration.collect(old);
  const migrated = migration.upgradeHistory(old);
  expect(migrated.snapshots).toEqual(old.snapshots);
  expect(migrated.future).toEqual(old.future);
  for (const [id, r] of Object.entries(migrated.diagramRevisions) as [string, any][]) {
    expect(r.diagram.revisionId).toBe(id);
    expect(r.nodeRefs).toEqual(old.diagramRevisions[id].nodeRefs);
    expect(r.parentId).toBe(old.diagramRevisions[id].parentId);
    if (r.parentId) expect(r.diagramId).toBe(migrated.diagramRevisions[r.parentId].diagramId);
  }
  const restored = new CanvasHistory(documentFromHistory(migrated), initialCanvasState(), migrated);
  expect(restored.document().scene.contents.overview.content.ascii).toBe('Before');
  restored.navigate(true);
  expect(restored.document().scene.contents.overview.content.ascii).toBe('After');
  expect(migration.upgradeHistory(migrated)).toEqual(migrated);
});

it('keeps identical local IDs in independent histories distinct and reuses identities across forks', () => {
  const a = oldHistory(), b = oldHistory(), fork = { ...a, contextId: 'fork' };
  const migration = new IdentityMigration(); migration.collect([a, b, fork]);
  const ma = migration.upgradeHistory(a), mb = migration.upgradeHistory(b), mf = migration.upgradeHistory(fork);
  const identity = (h: any) => h.diagramRevisions[h.snapshots[h.headId].diagramBindings.overview].diagramId;
  expect(identity(ma)).not.toBe(identity(mb)); expect(identity(mf)).toBe(identity(ma));
});

it('converts legacy proposal stacks without dropping undo/redo or changing their content', () => {
  const old = oldHistory();
  const before = { document: documentFromHistory(old), canvas: initialCanvasState() };
  const after = { document: documentFromHistory(old, old.future[0]), canvas: initialCanvasState() };
  const session = { schemaVersion: 1, id: 'change-test', projectId: 'project', title: 'Test', description: '', status: 'draft', version: 1,
    createdAt: 'now', updatedAt: 'now', changes: [], receipts: {}, documents: [{ id: 'document', name: 'Canvas', version: 1,
      baseline: before, proposed: before, past: [after], future: [after] }] };
  const m = new IdentityMigration(); m.collect(session);
  const next = m.session(session), d = next.documents[0];
  validateCanvasHistory(d.history);
  expect(d.history.past).toHaveLength(1); expect(d.history.future).toHaveLength(1);
  const h = new CanvasHistory(d.proposed.document, d.proposed.canvas, d.history);
  h.navigate(true); expect(h.document().scene.contents.overview.content.ascii).toBe('After');
});

const roots: string[] = [];
afterEach(async () => { await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true }))); });
it('stages old catalogs without touching source, rejects concurrent writes, and publishes with a complete backup', async () => {
  const root = await mkdtemp(path.join(tmpdir(), 'diagram-migration-test-')); roots.push(root);
  const source = path.join(root, 'source'), stage = path.join(root, 'stage');
  const old = oldHistory();
  const { mkdir } = await import('node:fs/promises'); await mkdir(path.join(source, 'canvases'), { recursive: true });
  const catalog = { schemaVersion: 1, projectId: 'project', representations: {}, revisions: { r: { representationId: 'rep', content: { kind: 'canvas-history', history: old } },
    legacy: { representationId: 'rep-legacy', content: { kind: 'mapping-canvas', scene: documentFromHistory(old).scene } } } };
  const file = path.join(source, 'canvases/catalog.json'), original = JSON.stringify(catalog);
  await writeFile(file, original);
  await writeFile(path.join(source, 'project.json'), JSON.stringify({ id: 'project' }));
  await prepareMigration(source, stage);
  expect(await readFile(file, 'utf8')).toBe(original);
  const restored = await new CanvasCatalogStore(stage).loadRepresentationCatalog('project');
  expect(Object.values(restored.revisions).every(r => r.content?.kind === 'canvas-history')).toBe(true);
  await expect(publishMigration(stage)).rejects.toThrow('Stage must pass verification');
  await verifyMigration(stage);
  await writeFile(file, original + '\n');
  await expect(publishMigration(stage)).rejects.toThrow('Source changed');
  await writeFile(file, original);
  const result = await publishMigration(stage);
  expect(await readFile(path.join(result.backup, 'canvases/catalog.json'), 'utf8')).toBe(original);
  expect(await prepareMigration(source, path.join(root, 'second'))).toEqual({ alreadyMigrated: true });
});

it('fails on missing ancestry instead of guessing identity', () => {
  const old = oldHistory(), child: any = Object.values(old.diagramRevisions).find((r: any) => r.parentId);
  delete old.diagramRevisions[child.parentId];
  const m = new IdentityMigration(); m.collect(old);
  expect(() => m.upgradeHistory(old)).toThrow('Missing revision parent');
});

import { DiagramPersistence } from '../../../../domain/core/diagrams/diagramPersistence';
import { canvasSaveFixture } from '../../../../tests/support/mappingDiagram';
import { mkdtemp, readFile, writeFile, readdir, rm, mkdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, expect, it, vi } from 'vitest';
import { CanvasCatalogStore } from '../canvasCatalogStore';
import { DiagramRevisionStore } from '../diagramRevisionStore';
import { revisionFixture } from '../../../../tests/support/diagramRevisions';
import { sourceBindingFromLocation } from '../../../../domain/core/diagrams/diagram';
import { singleDiagramScene } from '../../../../domain/core/diagrams/projectDiagramCanvas';
import { documentFromHistory } from '../../../../domain/core/diagrams/canvasHistory';
import { MappingDocumentController } from '../../../../domain/mapping/workspace/mappingDocumentController';
import { mappingDocumentFromScene } from '../../../../domain/mapping/workspace/mappingDocument';
import { initialCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';
import { MappingWorkspaceStore } from '../../../mapping/persistence/workspace/mappingWorkspaceStore';
import { DiagramChangeSessionStore } from '../../../mapping/changes/diagramChangeSessionStore';
import type { DiagramChangeSession } from '../../../../domain/mapping/changes/diagramChangeSession';

const roots: string[] = [];
afterEach(async () => { await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true }))); });
async function setup() {
  const root = await mkdtemp(path.join(tmpdir(), 'diagram-records-')); roots.push(root);
  const records = new DiagramRevisionStore(root), service = new DiagramPersistence(records);
  const canvas = initialCanvasState();
  const controller = new MappingDocumentController(mappingDocumentFromScene(singleDiagramScene('Original')), canvas, 0, undefined, undefined, undefined);
  controller.applyUpdate(0, [{ method: 'replace', nodeId: 'grid:overview', ascii: 'Changed' }]);
  return { root, records, service, controller, canvas };
}
it('retains named CanvasViews when opening a saved canvas through the current-history loader', async () => {
  const { controller, service } = await setup();
  const recording = controller.canvasView(controller.getSnapshot().version, { operation: 'start', name: 'Earlier state' }).recording!;
  controller.canvasView(controller.getSnapshot().version, { operation: 'stop' });
  controller.applyUpdate(controller.getSnapshot().version, [{ method: 'replace', nodeId: 'grid:overview', ascii: 'Latest state' }]);
  const stored = await service.persist(controller.exportHistory());
  const history = await service.currentHistory(stored);
  const restored = new MappingDocumentController(documentFromHistory(history), initialCanvasState(), 0, undefined, undefined, history);
  restored.canvasView(0, { operation: 'apply', viewId: recording.id });
  expect(restored.getSnapshot().document.scene.contents.overview.content.ascii).toBe('Changed');
});

it('stores diagram revisions and bindings separately and restores durable undo in a new process', async () => {
  const { root, service, controller } = await setup();
  const catalog = new CanvasCatalogStore(root, service);
  const saved = await catalog.saveMappingDiagram('project', { name: 'Canvas', scene: controller.getSnapshot().document.scene, history: controller.exportHistory() });
  const disk = JSON.parse(await readFile(path.join(root, 'canvases/catalog.json'), 'utf8'));
  const history = disk.revisions[saved.representation.currentRevisionId].content.history;
  expect(history.diagramRevisions).toBeUndefined();
  expect(history.diagramHistory.$diagramRecord).toBe('history');
  expect(history.snapshots[history.headId].diagramBindings).toBeUndefined();
  expect(history.snapshots[history.headId].format).toBe('canvas-checkpoint-v1');
  expect(history.snapshots[history.headId].document).toBeUndefined();
  expect((await readdir(path.join(root, 'diagrams/revision'))).length).toBeGreaterThan(1);
  const loaded = await new CanvasCatalogStore(root).loadRepresentationCatalog('project');
  expect(loaded).toEqual(JSON.parse(JSON.stringify(saved.catalog)));
  const stored = loaded.revisions[saved.representation.currentRevisionId].content;
  if (stored?.kind !== 'canvas-history') throw new Error();
  const reopened = new MappingDocumentController(documentFromHistory(stored.history), initialCanvasState(), 0, undefined, undefined, stored.history);
  reopened.undo(); expect(reopened.resolveDiagram('overview').ascii).toBe('Original');
  reopened.undo(true); expect(reopened.resolveDiagram('overview').ascii).toBe('Changed');
});

it('reads the legacy catalog without modifying it, then publishes to the canvas store', async () => {
  const { root, controller } = await setup();
  const catalog = new CanvasCatalogStore(root);
  const saved = await catalog.saveMappingDiagram('project', { name: 'Before', scene: controller.getSnapshot().document.scene, history: controller.exportHistory() });
  await mkdir(path.join(root, 'representations'));
  const original = JSON.stringify(saved.catalog);
  await writeFile(path.join(root, 'representations/catalog.json'), original);
  await rm(path.join(root, 'canvases'), { recursive: true });
  await rm(path.join(root, 'diagrams'), { recursive: true });
  expect(await catalog.loadRepresentationCatalog('project')).toEqual(JSON.parse(original));
  await catalog.saveMappingDiagram('project', canvasSaveFixture({ name: 'After', representationId: saved.representation.id,
    expectedRevisionId: saved.representation.currentRevisionId, scene: controller.getSnapshot().document.scene }));
  expect(await readFile(path.join(root, 'representations/catalog.json'), 'utf8')).toBe(original);
  expect((await catalog.loadRepresentationCatalog('project')).representations[saved.representation.id].name).toBe('After');
});

it('does not publish a canvas if diagram persistence fails', async () => {
  const { root, records, service, controller } = await setup();
  const catalog = new CanvasCatalogStore(root, service);
  const first = await catalog.saveMappingDiagram('project', canvasSaveFixture({ name: 'Before', scene: controller.getSnapshot().document.scene }));
  const before = await readFile(path.join(root, 'canvases/catalog.json'), 'utf8');
  vi.spyOn(records, 'put').mockRejectedValue(new Error('Disk full'));
  await expect(async () => catalog.saveMappingDiagram('project', canvasSaveFixture({ name: 'After', representationId: first.representation.id,
    expectedRevisionId: first.representation.currentRevisionId, scene: singleDiagramScene('New') }))).rejects.toThrow('Disk full');
  expect(await readFile(path.join(root, 'canvases/catalog.json'), 'utf8')).toBe(before);
});

it('externalizes workspace and change-session diagrams while keeping their public exports portable', async () => {
  const { root, service, controller, canvas } = await setup();
  const document = controller.getSnapshot().document, history = controller.exportHistory();
  const workspace = { schemaVersion: 3 as const, projectId: 'project', documents: [{ representationId: 'draft-test',
    name: 'Draft', savedName: '', revisionId: '', document, canvas, history, savedScene: JSON.stringify(document.scene) }] };
  const workspaces = new MappingWorkspaceStore(root, service);
  await workspaces.save('project', workspace);
  const raw = JSON.parse(await readFile(path.join(root, 'mapping-workspace.json'), 'utf8'));
  expect(raw.documents[0].document.scene.contents.overview.$diagramRecord).toBe('diagram');
  expect(raw.documents[0].history.diagramRevisions).toBeUndefined();
  expect(await new MappingWorkspaceStore(root).load('project')).toEqual(JSON.parse(JSON.stringify(workspace)));
  const time = new Date().toISOString();
  const session: DiagramChangeSession = { schemaVersion: 1, id: 'change-test', projectId: 'project', title: 'Proposal', description: '',
    status: 'draft', version: 0, createdAt: time, updatedAt: time, changes: [], migrations: [], receipts: {}, documents: [{ id: 'doc', name: 'Canvas',
      history, baseline: { document, canvas }, proposed: { document, canvas }, version: 0, past: [], future: [] }] };
  await new DiagramChangeSessionStore(root, service).write(session);
  const sessionDisk = JSON.parse(await readFile(path.join(root, 'mapping-change-sessions/project/change-test.manifest.json'), 'utf8'));
  const blob = async (id: string) => JSON.parse(await readFile(path.join(root, 'change-session-records', `${id}.json`), 'utf8'));
  const storedDoc = await blob(sessionDisk.documents.doc);
  expect((await blob(storedDoc.history.header)).diagramRevisions).toBeUndefined();
  expect((await blob(storedDoc.proposed)).document.scene.contents.overview.$diagramRecord).toBe('diagram');
  expect(await new DiagramChangeSessionStore(root).read('project', 'change-test')).toEqual(JSON.parse(JSON.stringify(session)));
  // Missing dependencies must be reported, not interpreted as an absent workspace.
  await rm(path.join(root, 'diagrams'), { recursive: true });
  await expect(workspaces.load('project')).rejects.toThrow();
});

it('rejects corrupted and escaping diagram references', async () => {
  const { root, records, service, controller } = await setup();
  const stored = await service.persist(controller.getSnapshot().document) as any;
  const ref = stored.scene.contents.overview;
  await writeFile(path.join(root, 'diagrams/diagram', `${ref.id}.json`), '{}');
  await expect(service.restore(stored)).rejects.toThrow('integrity');
  await expect(records.get('diagram', '../project')).rejects.toThrow('identity');
});

it('rejects saves without supplied history before publishing any catalog', async () => {
  const { root, controller } = await setup();
  const catalog = new CanvasCatalogStore(root);
  // @ts-expect-error Simulate an untyped HTTP/MCP caller omitting required history.
  await expect(catalog.saveMappingDiagram('project', { name: 'Missing history', scene: controller.getSnapshot().document.scene }))
    .rejects.toThrow('Canvas history is required');
  expect(await readdir(root)).not.toContain('canvases');
});

it('reads source bindings from canvas heads without loading past diagram revisions', async () => {
  const { root, records, service } = await setup();
  const source = sourceBindingFromLocation({ checkoutRoot: root, repositoryIdentity: 'repo' });
  const controller = new MappingDocumentController(mappingDocumentFromScene(singleDiagramScene('Original', source)), initialCanvasState());
  controller.applyUpdate(0, [{ method: 'replace', nodeId: 'grid:overview', ascii: 'Changed' }]);
  const history = controller.exportHistory();
  const stored = await service.persist(history) as any;
  const get = vi.spyOn(records, 'get');
  expect(await service.sourceBindings([stored, stored])).toEqual([source]);
  expect(get.mock.calls.filter(([kind]) => kind === 'revision')).toHaveLength(Object.keys(history.snapshots[history.headId].diagramBindings).length);
  expect(await service.sourceBindings([history])).toEqual([source]);
});

it('shares source metadata reads and refreshes after another store publishes a canvas', async () => {
  const { root, service } = await setup();
  const first = sourceBindingFromLocation({ checkoutRoot: root, repositoryIdentity: 'first' });
  const second = sourceBindingFromLocation({ checkoutRoot: path.join(root, 'second'), repositoryIdentity: 'second' });
  const store = new CanvasCatalogStore(root, service);
  await store.saveMappingDiagram('project', canvasSaveFixture({ name: 'First', scene: singleDiagramScene('First', first) }));
  const read = vi.spyOn(service, 'sourceBindings');
  expect(await Promise.all([store.loadDiagramSourceBindings('project'), store.loadDiagramSourceBindings('project')])).toEqual([[first], [first]]);
  expect(read).toHaveBeenCalledTimes(1);
  await new CanvasCatalogStore(root).saveMappingDiagram('project', canvasSaveFixture({ name: 'Second', scene: singleDiagramScene('Second', second) }));
  expect(await store.loadDiagramSourceBindings('project')).toEqual([first, second]);
  expect(read).toHaveBeenCalledTimes(2);
  await expect(store.loadDiagramSourceBindings('another-project')).rejects.toThrow('another Project');
  expect(await store.loadDiagramSourceBindings('project')).toEqual([first, second]);
});

