          });
        }
        if(started!==undefined && time-started>=400) { window.changeFocusDone=true; return; }
        requestAnimationFrame(record);
      };
      requestAnimationFrame(record);
    })()`);
    await click('[data-change-id]', 'Add detail2 Add diagram');
