    await key('Enter', 'Enter', 13); await waitFor(async () => await focusedLine() === 3);
    await key('Enter', 'Enter', 13); await waitFor(async () => await focusedLine() === 4);
    await key('Enter', 'Enter', 13); await waitFor(async () => await focusedLine() === 3);
    await key('Enter', 'Enter', 13, 8); await waitFor(async () => await focusedLine() === 4);
