// Run with node --import tsx after npm run build.
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, writeFile, rm } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { canvasSaveFixture } from '../../support/mappingDiagram.ts';
import { singleDiagramScene } from '../../../domain/core/diagrams/projectDiagramCanvas.ts';
import { revisionFixture } from '../../support/diagramRevisions.ts';
import { diagramContentNodes } from '../../../domain/core/diagrams/diagramContentNodes.ts';
import { defaultArrowAppearance } from '../../../domain/core/diagrams/diagramConnection.ts';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'edge-obstacles-'));
let server;
try {
  await seedMappingFixture(root, { ascii: 'Fixture', nodes: [] });
  const scene = singleDiagramScene('Fixture');
  const contents = {
    source: 'Source\n|\n|\n|\n`-- From', target: 'Target\n|\n|\n|\n`-- To',
    blocker: 'Blocker\n|-- Branch\n|   |-- First long label\n|   |-- Second long label\n|   |-- Third long label\n|   |-- Fourth long label\n|   |-- Fifth long label\n|   `-- Sixth long label\n`-- Tail',
    ports: 'Root\n|-- Apply variant\n|   |-- A long intervening label that should not force a detour to the right\n|   `-- Another long intervening label to avoid\n`-- Persistence',
    laneSource: 'Lane source\n`-- Exit', laneTarget: 'Lane target\n|-- One\n`-- Two',
    gutterSource: 'Outside\n`-- From', gutter: 'Gutter\n' + '|\n'.repeat(7) + '|-- Destination\n' + '|\n'.repeat(7) + '`-- Tail'
  };
  scene.contents = Object.fromEntries(Object.entries(contents).map(([id, ascii]) => [id, revisionFixture().create({ id, revision: 0, ascii, structureKind: 'tree' }).diagram]));
  scene.root.children = Object.keys(contents).map(id => ({ id, kind: 'diagram', contentId: id, collapsed: false,
    position: { column: { source: 0, blocker: 25, target: 70, ports: 0, gutterSource: 45, gutter: 65, laneSource: 45, laneTarget: 75 }[id],
      row: { ports: 15, gutterSource: 31, gutter: 24, laneSource: 21, laneTarget: 21 }[id] ?? 0 } }));
  const from = diagramContentNodes(scene.contents.source.content).find(node => node.label === 'From');
  const edge = { id: 'around-text', source: { kind: 'content-node', displayNodeId: 'grid:source', contentNodeId: from.id,
    revisionId: scene.contents.source.content.revisionId, side: 'right' },
    target: { kind: 'content-node', displayNodeId: 'grid:target', side: 'left', offset: 0.9,
      contentNodeId: diagramContentNodes(scene.contents.target.content).find(node => node.label === 'To').id, revisionId: scene.contents.target.content.revisionId }, appearance: defaultArrowAppearance };
  const portAnchor = label => ({ kind: 'content-node', displayNodeId: 'grid:ports',
    contentNodeId: diagramContentNodes(scene.contents.ports.content).find(node => node.label === label).id,
    revisionId: scene.contents.ports.content.revisionId, side: 'horizontal' });
  const flexibleEdge = { id: 'choose-sides', source: portAnchor('Apply variant'), target: portAnchor('Persistence'), appearance: defaultArrowAppearance };
  const gutterAnchor = (id, label, side) => ({ kind: 'content-node', displayNodeId: `grid:${id}`,
    contentNodeId: diagramContentNodes(scene.contents[id].content).find(node => node.label === label).id,
    revisionId: scene.contents[id].content.revisionId, side });
  const gutterEdge = { id: 'cross-guide', source: gutterAnchor('gutterSource', 'From', 'right'), target: gutterAnchor('gutter', 'Destination', 'left'), appearance: defaultArrowAppearance };
  const laneEdges = ['lane-a', 'lane-b', 'lane-c'].map(id => ({ id,
    source: gutterAnchor('laneSource', 'Lane source', 'right'),
    target: { kind: 'box', displayNodeId: 'grid:laneTarget', side: 'left' }, appearance: defaultArrowAppearance }));
  const file = path.join(root, '.diagrams/representations/catalog.json'), catalog = JSON.parse(await readFile(file, 'utf8'));
  catalog.revisions['revision-overview'].content = { kind: 'canvas-history', history: canvasSaveFixture({ name: 'Routing fixture', scene, edges: [edge, flexibleEdge, gutterEdge, ...laneEdges] }).history };
  await writeFile(file, JSON.stringify(catalog));
  const port = await new Promise(resolve => { const socket=createServer(); socket.listen(0,'127.0.0.1',()=>{const port=socket.address().port;socket.close(()=>resolve(port));}); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', 'preview', '--http', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { detached: true, env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: path.join(root,'.diagrams') }, stdio:['ignore','ignore','pipe'] });
  let errors='';server.stderr.on('data',chunk=>{errors+=chunk;});
  await waitFor(async()=>(await fetch(url).catch(()=>null))?.ok,{timeoutMs:20000}).catch(error=>{throw Error(`${error}\n${errors}`);});
  await withHeadlessBrowser({url:`${url}/mapping?diagram=representation-overview`,width:1600,height:1050,chromePath:process.env.CHROME_PATH,
    arguments:['--no-sandbox','--disable-gpu']},async({cdp})=>{
    cdp.on('Page.javascriptDialogOpening', () => cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    await cdp.send('Page.enable');await cdp.send('Runtime.enable');
    const exceptions=[];cdp.on('Runtime.exceptionThrown',event=>exceptions.push(event.exceptionDetails.text));
    const routeSelector='[data-connection-id="around-text"] .diagram-connection-hit';
    const route=()=>evaluate(cdp,`document.querySelector(${JSON.stringify(routeSelector)})?.getAttribute('d')`);
    const mouse=(type,p,clickCount=1)=>cdp.send('Input.dispatchMouseEvent',{type,...p,button:'left',buttons:type==='mouseReleased'?0:1,clickCount});
    const click=async(selector,label)=>{
      let p;await waitFor(async()=>{p=await evaluate(cdp,`(()=>{const el=[...document.querySelectorAll(${JSON.stringify(selector)})].find(el=>!el.disabled&&(!${JSON.stringify(label)}||el.textContent.trim()===${JSON.stringify(label)}));if(!el)return null;
        const r=el.getBoundingClientRect(),p={x:r.x+r.width/2,y:r.y+r.height/2};return el.contains(document.elementFromPoint(p.x,p.y))?p:null;})()`);return !!p;}).catch(async error=>{
          await captureScreenshot(cdp,{output:process.env.EDGE_OBSTACLES_SCREENSHOT??path.join(root,'failure.png')});
          const detail=await evaluate(cdp,`(()=>{const el=document.querySelector(${JSON.stringify(selector)});if(!el)return 'missing';const r=el.getBoundingClientRect();return {element:el.outerHTML,hit:document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)?.outerHTML};})()`);
          throw Error(String(error)+' '+JSON.stringify(detail));
        });
      await mouse('mousePressed',p);await mouse('mouseReleased',p);
    };
    const avoidsText=async()=>{
      const result=await evaluate(cdp,`(()=>{const path=document.querySelector(${JSON.stringify(routeSelector)}),m=path.getScreenCTM();
        const rows=[...document.querySelectorAll('[data-native-node="grid:blocker"] .diagram-content-node')].map(label=>{
          const r=label.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height,text:label.textContent};});
        const violations=[];for(let i=1;i<path.getTotalLength();i+=1){const p=path.getPointAtLength(i),s=new DOMPoint(p.x,p.y).matrixTransform(m);
          if(rows.some(r=>s.x>r.x&&s.x<r.x+r.width&&s.y>r.y&&s.y<r.y+r.height))violations.push({x:s.x,y:s.y});}
        return {violations:violations.slice(0,3),length:path.getTotalLength(),labels:rows,path:path.getAttribute('d')};})()`);
      if(result.violations.length){console.error(JSON.stringify(result));await captureScreenshot(cdp,{output:process.env.EDGE_OBSTACLES_SCREENSHOT??path.join(root,'failure.png')});}
      assert.deepEqual(result.violations,[],'Route must avoid every visible text label');return result.length;
    };
    await waitForSelector(cdp,routeSelector);
    await waitFor(async()=>await evaluate(cdp,"document.querySelector('[data-connection-id=\"around-text\"]').dataset.geometrySource==='measured'"));
    const checkSides = async () => {
      await waitFor(async()=>await evaluate(cdp,"document.querySelector('[data-connection-id=\"choose-sides\"]')?.dataset.geometrySource==='measured'"));
      const bounds = await evaluate(cdp,"(()=>{const p=document.querySelector('[data-connection-id=\"choose-sides\"] .diagram-connection-hit'),b=p.getBBox();return {width:b.width,length:p.getTotalLength()};})()");
      assert.ok(bounds.width < 180 && bounds.length < 350, `Flexible sides must choose the short left channel: ${JSON.stringify(bounds)}`);
    };
    await checkSides();
    const checkGuide = async () => {
      await waitFor(async()=>await evaluate(cdp,"document.querySelector('[data-connection-id=\"cross-guide\"]')?.dataset.geometrySource==='measured'"));
      const route = await evaluate(cdp, `(()=>{const p=document.querySelector('[data-connection-id="cross-guide"] .diagram-connection-hit'),m=p.getScreenCTM(),b=p.getBBox();
        const labels=[...document.querySelectorAll('[data-native-node="grid:gutter"] .diagram-content-node')].map(e=>e.getBoundingClientRect());
        const first=p.getPointAtLength(0),last=p.getPointAtLength(p.getTotalLength());
        const start=new DOMPoint(first.x,first.y).matrixTransform(m),end=new DOMPoint(last.x,last.y).matrixTransform(m);
        const box=document.querySelector('[data-grid-box=gutter]').getBoundingClientRect();
        let crossesText=false;for(let i=1;i<p.getTotalLength();i++){const q=p.getPointAtLength(i),s=new DOMPoint(q.x,q.y).matrixTransform(m);
          crossesText ||= labels.some(r=>s.x>r.left&&s.x<r.right&&s.y>r.top&&s.y<r.bottom);}
        return {height:b.height,length:p.getTotalLength(),crossesGutter:start.x<box.left&&end.x>box.left+10,crossesText};})()`);
      assert.ok(route.height < 1 && route.length < 180 && route.crossesGutter && !route.crossesText,
        `Cross the tall guide directly, avoiding labels: ${JSON.stringify(route)}`);
    };
    await checkGuide();
    const checkLanes = async () => {
      await waitFor(async()=>await evaluate(cdp, `[...document.querySelectorAll('[data-connection-id^="lane-"]')].length===3 &&
        [...document.querySelectorAll('[data-connection-id^="lane-"]')].every(e=>e.dataset.geometrySource==='measured')`));
      const lanes = await evaluate(cdp, `(()=>{
        const root=[...document.querySelectorAll('[data-native-node="grid:laneTarget"] .diagram-content-node')].find(e=>e.textContent==='Lane target').getBoundingClientRect();
        return [...document.querySelectorAll('[data-connection-id^="lane-"] .diagram-connection-hit')].map(p=>{
          const end=p.getPointAtLength(p.getTotalLength()),m=p.getScreenCTM(),screen=new DOMPoint(end.x,end.y).matrixTransform(m);
          return {path:p.getAttribute('d'),dx:screen.x-root.left,dy:screen.y-(root.top+root.height/2)};
        });})()`);
      assert.equal(new Set(lanes.map(l=>l.path)).size,3,'Three shared runs must occupy different lanes');
      for(const lane of lanes) assert.ok(Math.abs(lane.dx)<1 && Math.abs(lane.dy)<1,`Diagram destination must terminate on its root label: ${JSON.stringify(lane)}`);
      return lanes.map(l=>l.path);
    };
    const initialLanes=await checkLanes();
    const initial=await route(), initialLength=await avoidsText();
    await captureScreenshot(cdp,{output:process.env.EDGE_OBSTACLES_SCREENSHOT??path.join(root,'routing.png')});
    await cdp.send('Input.dispatchMouseEvent',{type:'mouseWheel',x:1300,y:800,deltaX:40,deltaY:30});
    assert.equal(await route(),initial,'Panning must not change canvas-space routes');
    assert.deepEqual(await checkLanes(),initialLanes,'Panning must preserve spaced lanes');
    const select=await evaluate(cdp,"(()=>{const r=document.querySelector('[data-grid-box=blocker]').getBoundingClientRect();return {x:r.right-8,y:r.bottom-8};})()");
    await mouse('mousePressed',select);await mouse('mouseReleased',select);await mouse('mousePressed',select,2);await mouse('mouseReleased',select,2);
    await waitForSelector(cdp,'[data-diagram-move-handle="grid:blocker"]');
    const handle=await evaluate(cdp,"(()=>{const r=document.querySelector('[data-diagram-move-handle=\"grid:blocker\"]').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2};})()");
    await evaluate(cdp,"window.__routingLongTasks=[];window.__routingObserver=new PerformanceObserver(list=>window.__routingLongTasks.push(...list.getEntries().map(entry=>entry.duration)));window.__routingObserver.observe({type:'longtask'});");
    await mouse('mouseMoved',handle);await mouse('mousePressed',handle);
    for(let i=1;i<=12;i++)await mouse('mouseMoved',{x:handle.x,y:handle.y+i*20});
    await waitFor(async()=>await route()!==initial); // The non-endpoint obstacle moves before the gesture is saved.
    await avoidsText();
    await mouse('mouseReleased',{x:handle.x,y:handle.y+240});
    await waitFor(async()=>Number(await evaluate(cdp,"document.querySelector('[data-grid-box=blocker]').dataset.gridRow"))>0);
    const movedLength=await avoidsText();assert.ok(movedLength<initialLength,'Moving the blocker out of the channel should shorten the route');
    const longTasks=await evaluate(cdp,'window.__routingObserver.disconnect();window.__routingLongTasks');
    await click('.mapping-grid-tools button','Undo');
    await waitFor(async()=>Number(await evaluate(cdp,"document.querySelector('[data-grid-box=blocker]').dataset.gridRow"))===0);
    await avoidsText();
    await cdp.send('Input.dispatchKeyEvent',{type:'keyDown',key:'Escape',code:'Escape',windowsVirtualKeyCode:27});
    await cdp.send('Input.dispatchKeyEvent',{type:'keyUp',key:'Escape',code:'Escape',windowsVirtualKeyCode:27});
    await click('[data-subtree-owner="grid:blocker"][data-subtree-line="2"]');
    await waitFor(async()=>await evaluate(cdp,"document.querySelector('[data-subtree-owner=\"grid:blocker\"][data-subtree-line=\"2\"]').getAttribute('aria-expanded')==='false'"));
    assert.ok(await avoidsText()<initialLength,'Hidden rows must stop obstructing routes');
    await click('[aria-label="Menu"]');await click('.mapping-workspace-actions button','Save workspace');
    await waitFor(async()=>{const result=await fetch(url+'/api/mapping/workspace').then(r=>r.json());return (result.workspace??result)?.documents?.[0]?.canvas.diagramViews?.['grid:blocker']?.collapsedContentNodeIds.length===1;});
    await evaluate(cdp,'window.__beforeRoutingReload=true');await cdp.send('Page.reload',{ignoreCache:true});
    await waitFor(async()=>{try{return await evaluate(cdp,'window.__beforeRoutingReload!==true&&document.readyState==="complete"');}catch{return false;}});
    await waitForSelector(cdp,routeSelector);await avoidsText();await checkSides();await checkGuide();await checkLanes();
    assert.deepEqual(exceptions,[]);
    console.log(JSON.stringify({result:'PASS root destinations, shared lanes, guide crossing, label avoidance, flexible attachment, pan stability, live obstacle drag, undo, collapse and reload',initialLength,movedLength,dragLongTasksMs:longTasks}));
  });
}finally{
  if(server){try{process.kill(-server.pid,'SIGTERM');}catch{}}
  await rm(root,{recursive:true,force:true});
}

sources.tests/browser/mapping/browser-highlight-:
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { canvasSaveFixture } from '../../support/mappingDiagram.ts';
import { emptyCanvasDocument } from '../../../domain/core/diagrams/canvasTransfer.ts';
import { revisionFixture } from '../../support/diagramRevisions.ts';
import { diagramContentNodes } from '../../../domain/core/diagrams/diagramContentNodes.ts';
import { defaultArrowAppearance } from '../../../domain/core/diagrams/diagramConnection.ts';
import { DiagramStore } from '../../../infrastructure/core/persistence/store.ts';
import { initialCanvasState } from '../../../domain/mapping/workspace/mappingWorkspace.ts';
const { evaluate, waitFor, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'highlight-projection-browser-'));
let server;
try {
  await seedMappingFixture(root, { ascii: 'Projection fixture', nodes: [] });
  const catalogPath = path.join(root, '.diagrams/representations/catalog.json');
  const catalog = JSON.parse(await readFile(catalogPath, 'utf8'));
  const document = emptyCanvasDocument(), service = revisionFixture();
  const positions = [[0, 0], [55, 5], [18, 26], [80, 40]];
  const names = ['API gateway', 'Worker service', 'Database', 'Not highlighted'];
  document.scene.contents = Object.fromEntries(names.map((name, i) => {
    const id = `d${i}`;
    let diagram = service.create({ id, revision: 0, ascii: `${name}\n|-- Input\n\x60-- Output`, structureKind: 'tree' }).diagram;
    if (i < 3) diagram = service.revise(diagram.revisionId, { kind: 'highlights', highlights: [
      { id: `highlight-${i}`, color: ['yellow', 'blue', 'green'][i], ...(i === 1 ? { contentNodeId: diagramContentNodes(diagram.content)[0].id } : {}) }
    ] }).diagram;
    return [id, diagram];
  }));
  document.scene.root.children = names.map((_, i) => ({ id: `d${i}`, kind: 'diagram', contentId: `d${i}`, collapsed: false, position: { column: positions[i][0], row: positions[i][1] } }));
  document.edges = [[0, 1], [1, 2], [0, 3]].map(([a, b], i) => ({ id: `edge-${i}`,
    source: { kind: 'content-node', displayNodeId: `grid:d${a}`, contentNodeId: diagramContentNodes(document.scene.contents[`d${a}`].content)[0].id,
      revisionId: document.scene.contents[`d${a}`].content.revisionId, side: 'auto' },
    target: { kind: 'box', displayNodeId: `grid:d${b}`, side: 'auto' }, appearance: { ...defaultArrowAppearance, label: 'calls' } }));
  catalog.representations['representation-overview'].name = 'Services';
  catalog.revisions['revision-overview'].content = { kind: 'canvas-history', history: canvasSaveFixture({ name: 'Services', scene: document.scene, edges: document.edges }).history };
  // Old checkpoints can dwarf the current scene. Projection must not copy them.
  if (process.env.PROJECTION_MEMORY === '1') {
    const history = catalog.revisions['revision-overview'].content.history;
    const head = history.snapshots[history.headId];
    for (let i = 0; i < 24; i++) {
      const id = `archived-${i}`;
      history.snapshots[id] = { ...head, id, parentId: history.past.at(-1),
        view: { ...head.view, memoryFixture: `${i}:` + 'archived conversation '.repeat(50_000) } };
      history.past.push(id);
    }
    head.parentId = history.past.at(-1);
    head.view = initialCanvasState();
    await writeFile(path.join(root, '.diagrams/mapping-workspace.json'), JSON.stringify({
      schemaVersion: 3, projectId: catalog.projectId, activeDocumentId: 'representation-overview', transfers: [],
      documents: [{ representationId: 'representation-overview', name: 'Services', savedName: 'Services',
        revisionId: 'revision-overview', savedScene: JSON.stringify(document.scene), savedEdges: JSON.stringify(document.edges),
        document, canvas: initialCanvasState(), history }]
    }));
  }
  await writeFile(catalogPath, JSON.stringify(catalog));
  const port = await new Promise(resolve => { const socket = createServer(); socket.listen(0, '127.0.0.1', () => { const { port } = socket.address(); socket.close(() => resolve(port)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', '--http', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'], {
    cwd: process.cwd(), env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: new DiagramStore(root).storeRoot, NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'ignore', 'pipe']
  });
  let errors = ''; server.stderr.on('data', chunk => { errors += chunk; });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 25000 }).catch(error => { throw Error(`${error}\n${errors}`); });
  await withHeadlessBrowser({ url: `${url}/mapping?diagram=representation-overview`, width: 1600, height: 1050, chromePath: process.env.CHROME_PATH,
    arguments: ['--disable-gpu', ...(process.platform === 'linux' ? ['--no-sandbox'] : [])] }, async ({ cdp }) => {
    await cdp.send('Runtime.enable'); await cdp.send('Page.enable');
    cdp.on('Page.javascriptDialogOpening', () => cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    const exceptions = []; cdp.on('Runtime.exceptionThrown', e => exceptions.push(e.exceptionDetails.text));
    const click = async (selector, text) => {
      let point;
      await waitFor(async () => {
        point = await evaluate(cdp, `(() => {
          const el = [...document.querySelectorAll(${JSON.stringify(selector)})].find(el => !el.disabled && !el.closest('[inert]') && ${text ? `el.textContent.trim() === ${JSON.stringify(text)}` : 'true'});
          if (!el) return null;
          const r = el.getBoundingClientRect(), p = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
          return r.width && r.height && el.contains(document.elementFromPoint(p.x, p.y)) ? p : null;
        })()`); return !!point;
      }, { timeoutMs: 15000 });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...point, button: 'left', buttons: 1, clickCount: 1 });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...point, button: 'left', clickCount: 1 });
    };
    const key = async (key, code, windowsVirtualKeyCode, modifiers = 0) => {
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode, modifiers });
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode });
    };
    const persisted = async predicate => {
      let workspace;
      await waitFor(async () => { const value = await fetch(url + '/api/mapping/workspace').then(r => r.json()); workspace = value?.workspace ?? value; return !!workspace && predicate(workspace); }, { timeoutMs: process.env.PROJECTION_MEMORY === '1' ? 60000 : 15000 }).catch(async error => {
        console.error(await evaluate(cdp, `document.body.innerText.slice(-3000)`)); throw error;
      });
      return workspace;
    };
    const child = workspace => workspace.documents.find(d => d.parentCanvasId === 'representation-overview');
    const positionsOf = doc => doc.document.scene.root.children.map(b => b.position);
    await click('[aria-label="Explorer mode"] button', 'Canvas'); await click('[aria-label="Canvas panels"] button', 'Actions');
    assert.equal(await evaluate(cdp, `[...document.querySelectorAll('.mapping-explorer-tabs button')].some(b => b.textContent === 'LLMs')`), false);
    await waitFor(() => evaluate(cdp, `!!document.querySelector('.mapping-canvas-actions button:not(:disabled)')`));
    if (process.env.PROJECTION_MEMORY === '1') await waitFor(() => evaluate(cdp,
      `!!document.querySelector('.mapping-document-view:not([hidden]) button[title="Undo (Ctrl+Z)"]:not(:disabled)')`));
    await waitFor(() => evaluate(cdp, `!!document.querySelector('.mapping-document-view:not([hidden]) [data-grid-box]')`));
    await evaluate(cdp, `void (window.__projectionSourceView = document.querySelector('.mapping-document-view:not([hidden])'))`);
    await cdp.send('HeapProfiler.collectGarbage');
    const heapBefore = (await cdp.send('Runtime.getHeapUsage')).usedSize;
    let heapPeak = heapBefore, sampling = false;
    const heapTimer = setInterval(async () => {
      if (sampling) return;
      sampling = true;
      try { heapPeak = Math.max(heapPeak, (await cdp.send('Runtime.getHeapUsage')).usedSize); } catch {}
      finally { sampling = false; }
    }, 50);
    let ws;
    try {
    await click('.mapping-canvas-actions button', 'Project Highlights');
    ws = await persisted(w => w?.documents?.some(d => d.parentCanvasId === 'representation-overview'));
    await waitFor(() => evaluate(cdp, `!!document.querySelector('.projection-layout-panel')`));
    } finally { clearInterval(heapTimer); }
    const retainedSource = await evaluate(cdp, 'window.__projectionSourceView.isConnected');
    await evaluate(cdp, 'delete window.__projectionSourceView');
    await cdp.send('HeapProfiler.collectGarbage');
    console.log('Projection memory:', JSON.stringify({ heapBeforeMB: heapBefore / 1e6, heapPeakMB: heapPeak / 1e6,
      heapAfterMB: (await cdp.send('Runtime.getHeapUsage')).usedSize / 1e6, retainedSource }));
    assert.equal(retainedSource, true, 'Projection retains the source editor/session');
    const projectedId = child(ws).representationId;
    const initial = positionsOf(child(ws));
    const layout = child(ws).canvas.projectionLayout;
    assert.deepEqual(layout.settings, { mode: 'compact', centroid: 'mean', attraction: 1, neighbors: 1, fidelity: 1, gap: 8 });
    assert.deepEqual(child(ws).document.scene.contents[layout.placeholderId].content.ascii.split('\n'), Array.from({ length: 35 }, () => ' '.repeat(65)));
    assert.equal(child(ws).document.scene.root.children.length, 4);
    assert.equal(child(ws).document.edges.length, 2);
    assert.deepEqual(ws.documents.find(d => d.representationId === 'representation-overview').document.scene, JSON.parse(JSON.stringify(document.scene)));
    if (process.env.PROJECTION_MEMORY === '1') {
      const archive = ws.documents.find(d => d.representationId === 'representation-overview').history;
      assert.equal(archive.snapshots['archived-0'].view.memoryFixture.length, 'archived conversation '.length * 50_000 + 2);
      assert.ok(archive.past.includes('archived-23'), 'Source undo archive remains available');
    }
    await waitFor(() => evaluate(cdp, `!!document.querySelector('.mapping-canvas-children [data-project-diagram="${projectedId}"]') && !!document.querySelector('.projection-layout-panel')`));
    await click('.mapping-document-view:not([hidden]) [title="Reset zoom and center diagram"]');
    await captureScreenshot(cdp, { output: process.env.PROJECTION_SCREENSHOT || path.join(root, 'projection-default.png') });
    await click('[aria-label="Filter diagrams"]');
    await cdp.send('Input.insertText', { text: 'Highlights' });
    assert.ok(await evaluate(cdp, `!!document.querySelector('[data-project-diagram="representation-overview"]') && !!document.querySelector('.mapping-canvas-children [data-project-diagram="${projectedId}"]')`), 'Filtering a child retains its ancestor');
    await key('a', 'KeyA', 65, 2); await key('Backspace', 'Backspace', 8);
    const rendered = () => evaluate(cdp, `[...document.querySelectorAll('.mapping-document-view:not([hidden]) [data-grid-box]')].filter(e => e.dataset.gridBox !== 'root').map(el => {const r=el.getBoundingClientRect();return {id:el.dataset.gridBox,x:r.x,y:r.y,w:r.width,h:r.height}})`);
    const before = await rendered();
    await click('.projection-layout-presets button', 'Tight');
    ws = await persisted(w => child(w)?.canvas.projectionLayout.settings.attraction === .9);
    assert.notDeepEqual(positionsOf(child(ws)), initial);
    await waitFor(async () => JSON.stringify(await rendered()) !== JSON.stringify(before));
    const compact = await rendered();
    assert.equal(compact.length, 4);
    for (let i = 0; i < compact.length; i++) for (let j = i + 1; j < compact.length; j++) {
      const a = compact[i], b = compact[j];
      assert.ok(a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y);
    }
    await click('.projection-layout-panel input[aria-label="Minimum gap"]');
    await key('End', 'End', 35);
    ws = await persisted(w => child(w)?.canvas.projectionLayout.settings.gap === 20);
    await click('.projection-layout-panel select[aria-label="Layout centroid"]');
    await key('End', 'End', 35); await key('Enter', 'Enter', 13);
    await persisted(w => child(w)?.canvas.projectionLayout.settings.centroid === 'placeholder');
    await click('.projection-layout-presets button', 'Original');
    ws = await persisted(w => child(w)?.canvas.projectionLayout.settings.mode === 'original');
    const originalPositions = positionsOf(child(ws));
    await click('.projection-layout-presets button', 'Default');
    ws = await persisted(w => child(w)?.canvas.projectionLayout.settings.attraction === 1 && child(w)?.canvas.projectionLayout.settings.gap === 8);
    assert.deepEqual(positionsOf(child(ws)), initial);
    await click('.projection-layout-presets button', 'Original');
    await persisted(w => child(w)?.canvas.projectionLayout.settings.mode === 'original');
    await click('.projection-layout-presets button', 'Balanced');
    ws = await persisted(w => child(w)?.canvas.projectionLayout.settings.attraction === .4);
    const savedPositions = positionsOf(child(ws));
    await captureScreenshot(cdp, { output: path.join(root, 'projection-layout.png') });
    console.log('Screenshot captured: projected child, preserved edges, bottom-right layout controls.');
    const previous = await evaluate(cdp, 'performance.timeOrigin');
    await cdp.send('Page.reload', { ignoreCache: true });
    await waitFor(async () => { try { return await evaluate(cdp, `performance.timeOrigin !== ${previous} && !!document.querySelector('.projection-layout-panel input[aria-label="Minimum gap"]')`); } catch { return false; } });
    assert.equal(await evaluate(cdp, 'document.querySelector(\'.projection-layout-panel input[aria-label="Closeness to centroid"]\').value'), '0.4');
    ws = await persisted(w => child(w)?.canvas.projectionLayout.settings.attraction === .4);
    assert.deepEqual(positionsOf(child(ws)), savedPositions);
    assert.ok(await evaluate(cdp, `!!document.querySelector('.mapping-canvas-children [data-project-diagram="${projectedId}"]')`));
    await click('[aria-label="Minimize layout settings"]');
    await waitFor(() => evaluate(cdp, `!!document.querySelector('.projection-layout-panel.is-minimized')`));
    await click('[aria-label="Expand layout settings"]');
    await click('.mapping-document-view:not([hidden]) [title="Reset zoom and center diagram"]');
    await key('z', 'KeyZ', 90, 2);
    ws = await persisted(w => child(w)?.canvas.projectionLayout.settings.mode === 'original');
    assert.deepEqual(positionsOf(child(ws)), originalPositions);
    await key('y', 'KeyY', 89, 2);
    ws = await persisted(w => child(w)?.canvas.projectionLayout.settings.attraction === .4);
    assert.deepEqual(positionsOf(child(ws)), savedPositions);
    // Project again from the child to prove recursive ancestry rather than a flat parent label.
    await click('[aria-label="Explorer mode"] button', 'Canvas'); await click('[aria-label="Canvas panels"] button', 'Actions'); await click('.mapping-canvas-actions button', 'Project Highlights');
    ws = await persisted(w => w.documents.some(d => d.parentCanvasId === projectedId));
    const grandchild = ws.documents.find(d => d.parentCanvasId === projectedId);
    await waitFor(() => evaluate(cdp, `!!document.querySelector('.mapping-canvas-children .mapping-canvas-children [data-project-diagram="${grandchild.representationId}"]')`));
    assert.equal(grandchild.document.scene.root.children.length, 4, 'Reprojection adds one fresh placeholder');
    await click('.mapping-document-view:not([hidden]) [title="Reset zoom and center diagram"]');
    await key('z', 'KeyZ', 90, 2);
    await persisted(w => w.activeDocumentId === projectedId && w.documents.find(d => d.representationId === grandchild.representationId)?.hidden);
    await key('y', 'KeyY', 89, 2);
    await persisted(w => w.activeDocumentId === grandchild.representationId && !w.documents.find(d => d.representationId === grandchild.representationId)?.hidden);
    await waitFor(() => evaluate(cdp, `!!document.querySelector('.projection-layout-panel')`));
    assert.deepEqual(exceptions, []);
    console.log('PASS: exact highlighted subset, internal edges, recursive Explorer ancestry, live presets and sliders, rendered nonoverlap, original reset, persistence, reload, undo/redo, and minimization.');
  });
} finally {
  server?.kill('SIGTERM');
  if (server && server.exitCode === null) await new Promise(resolve => { server.once('exit', resolve); setTimeout(resolve, 3000); });
  await rm(root, { recursive: true, force: true });
}

sources.tests/browser/mapping/browser-live-canva:
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { homedir, tmpdir } from 'node:os';
import { createServer } from 'node:net';
import { once } from 'node:events';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { WebSocket } from 'ws';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
import { sceneFromRevision } from '../../../domain/core/diagrams/projectDiagramCanvas.ts';
import { revisionFixture } from '../../support/diagramRevisions.ts';
import { canvasSaveFixture } from '../../support/mappingDiagram.ts';
const root = await mkdtemp(path.join(tmpdir(), 'live-canvas-'));
let server, socket, secondSocket;
try {
  await seedMappingFixture(root, { ascii: 'Root\n\n`-- Service', nodes: [{ id: 'service', label: 'Service', head: { line: 3, startColumn: 5, endColumn: 11 },
    sourceRanges: [{ path: 'fixture.ts', startLine: 1, endLine: 2 }] }] });
  const catalogPath = path.join(root, '.diagrams/representations/catalog.json');
  const catalog = JSON.parse(await readFile(catalogPath, 'utf8'));
  const scene = sceneFromRevision(catalog.revisions['revision-overview']);
  const diagrams = revisionFixture();
  scene.contents = Object.fromEntries(Object.entries(scene.contents).map(([id, diagram]) => [id, diagrams.create({ id, revision: 0,
    ascii: diagram.content.ascii, structureKind: diagram.content.structure.kind, source: diagram.sourceContext.binding,
    evidence: diagram.sourceContext.evidence, mappings: diagram.sourceContext.mappings }).diagram]));
  scene.contents.other = revisionFixture().create({ id: 'other', revision: 0, ascii: 'Other diagram\n|-- Worker\n`-- Tail', structureKind: 'tree' }).diagram;
  scene.root.children.push({ id: 'other', kind: 'diagram', contentId: 'other', collapsed: false, position: { column: 30, row: 0 } });
  catalog.revisions['revision-overview'].content = { kind: 'canvas-history', history: canvasSaveFixture({ name: 'Fixture', scene, edges: [] }).history };
  await writeFile(catalogPath, JSON.stringify(catalog));
  const port = await new Promise(resolve => { const s = createServer(); s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => resolve(p)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', '--http', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { detached: true, env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: path.join(root, '.diagrams'), NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'ignore', 'pipe'] });
  let errors = ''; server.stderr.on('data', c => { errors += c; });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 }).catch(e => { throw Error(`${e}\n${errors}`); });
  await withHeadlessBrowser({ url: `${url}/mapping`, width: 1800, height: 1100, chromePath: process.env.CHROME_PATH,
    arguments: ['--disable-gpu', ...(process.platform === 'linux' ? ['--no-sandbox'] : [])] }, async ({ cdp }) => {
    try {
    await cdp.send('Page.enable');
    cdp.on('Page.javascriptDialogOpening', () => cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    await cdp.send('Browser.grantPermissions', { origin: url, permissions: ['clipboardReadWrite', 'clipboardSanitizedWrite'] });
    await waitForSelector(cdp, '[data-grid-box="overview"]');
    let canvas;
    await waitFor(async () => { canvas = (await (await fetch(`${url}/api/mapping/agent/canvases`)).json())[0]; return canvas?.documents.length; });
    assert.ok(canvas.stableWorkspaceId, 'The localhost browser must advertise a protected stable tab identity');
    const statusText = () => evaluate(cdp, 'document.querySelector(".mapping-agent-status")?.textContent.trim()');
    await waitFor(async () => await statusText() === 'No agents connected');
    socket = new WebSocket(`${url.replace('http:', 'ws:')}/api/mapping/live`);
    const messages = []; socket.on('message', raw => messages.push(JSON.parse(raw.toString())));
    await once(socket, 'open');
    let attached;
    await waitFor(async () => {
      attached = messages.find(m => m.type === 'attached');
      if (!attached) socket.send(JSON.stringify({ type: 'attach', protocolVersion: 2, workspaceInstanceId: canvas.canvasId, documentId: canvas.documents[0].documentId, includeContext: true }));
      return attached;
    });
    assert.equal(attached.context.apiFormatVersion, 1);
    for (const node of attached.context.nodes) {
      assert.equal(node.apiFormatVersion, 1);
      assert.ok(!('contentNodes' in node));
      assert.ok(!node.diagram || !('content' in node.diagram));
      if (node.content) assert.ok(node.content.structure.nodes);
    }
    await waitFor(async () => await statusText() === '1 agent connected');
    secondSocket = new WebSocket(`${url.replace('http:', 'ws:')}/api/mapping/live`);
    await once(secondSocket, 'open');
    const secondAttached = once(secondSocket, 'message');
    secondSocket.send(JSON.stringify({ type: 'attach', protocolVersion: 2, workspaceInstanceId: canvas.canvasId, documentId: canvas.documents[0].documentId }));
    assert.equal(JSON.parse(String((await secondAttached)[0])).type, 'attached');
    await waitFor(async () => await statusText() === '2 agents connected');
    const statusBounds = await evaluate(cdp, `(() => {
      const status = document.querySelector('.mapping-agent-status'), actions = document.querySelector('.mapping-workspace-actions button');
      const a = status.getBoundingClientRect(), b = actions.getBoundingClientRect();
      return { left: a.left, right: a.right, buttonLeft: b.left, color: getComputedStyle(status).color, state: status.dataset.state };
    })()`);
    assert.equal(statusBounds.state, 'connected');
    assert.ok(statusBounds.left >= 0 && statusBounds.right < statusBounds.buttonLeft);
    if (process.env.LIVE_CANVAS_SCREENSHOT) await captureScreenshot(cdp, { output: process.env.LIVE_CANVAS_SCREENSHOT });
    secondSocket.close();
    await waitFor(async () => await statusText() === '1 agent connected');
    const get = () => fetch(`${url}/api/mapping/live/connections/${attached.connectionId}/selection`);
    assert.deepEqual(attached.regions, []); assert.deepEqual((await (await get()).json()).regions, []);
    const regions = new Map(); let diagramIds = attached.diagramIds ?? []; let sequence = attached.sequence; let consumed = messages.indexOf(attached) + 1;
    const sync = () => {
      for (const message of messages.slice(consumed)) if (message.type === 'selection.delta') {
        assert.equal(message.baseSequence, sequence);
        if (message.diagramIds !== undefined) diagramIds = message.diagramIds;
        message.removed.forEach(id => regions.delete(id));
        message.upserted.forEach(region => regions.set(region.id, region));
        sequence = message.sequence;
      }
      consumed = messages.length; return [...regions.values()];
    };
    const points = await evaluate(cdp, `(() => {
      const pre=document.querySelector('.mapping-document-view:not([hidden]) [data-native-node="grid:overview"] .mapping-poc-ascii');
      const r=pre.getBoundingClientRect(), scale=r.width/pre.offsetWidth;
      const probe=document.querySelector('.mapping-poc-cell-probe');
      const w=probe.offsetWidth/10, h=parseFloat(getComputedStyle(pre).lineHeight);
      return { start:{x:r.x+.3*w*scale,y:r.y+.3*h*scale},end:{x:r.x+10.3*w*scale,y:r.y+2.3*h*scale} };
    })()`);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...points.start, button: 'left', buttons: 1, modifiers: 2, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...points.end, button: 'left', buttons: 1, modifiers: 2 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...points.end, button: 'left', buttons: 0, modifiers: 2, clickCount: 1 });
    await waitFor(() => sync().some(region => region.text.includes('Service: fixture.ts:1-2')));
    const expected = 'Root       \n           \n`-- Service\nAssociated Code Entities:\nService: fixture.ts:1-2';
    assert.equal(sync()[0].text, expected);
    const response = await get(); assert.equal(response.status, 200); assert.equal((await response.json()).regions[0].text, expected);
    assert.equal((await fetch(`${url}/api/mapping/live/connections/${attached.connectionId}/selection`, { headers: { 'If-None-Match': response.headers.get('etag') } })).status, 304);
    const key = async (key, code, windowsVirtualKeyCode) => {
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode });
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode });
    };
    await key('c', 'KeyC', 67);
    await waitFor(async () => await evaluate(cdp, 'navigator.clipboard.readText()') === expected);
    // Leave the first region retained, then open another through the public UI.
    const click = async selector => {
      let point;
      await waitFor(async () => {
        point = await evaluate(cdp, `(() => { const el = document.querySelector(${JSON.stringify(selector)}); if (!el) return null;
          const r = el.getBoundingClientRect(), x = r.x + r.width / 2, y = r.y + r.height / 2;
          return el.contains(document.elementFromPoint(x, y)) ? { x, y } : null; })()`);
        return point;
      });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...point, button: 'left', buttons: 1, clickCount: 1 });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...point, button: 'left', buttons: 0, clickCount: 1 });
    };
    await waitFor(async () => await evaluate(cdp, 'document.querySelectorAll("[data-code-panel]").length === 0'));
    assert.equal(sync().length, 1);
    const beforeOutside = sync().map(region => region.id);
    const outside = await evaluate(cdp, `(()=>{const r=document.querySelector('[data-grid-box="other"]').getBoundingClientRect();return{x:r.right+20,y:r.bottom+30}})()`);
    await cdp.send('Input.dispatchMouseEvent', {type:'mousePressed',...outside,button:'left',buttons:1,clickCount:1});
    await cdp.send('Input.dispatchMouseEvent', {type:'mouseReleased',...outside,button:'left',buttons:0,clickCount:1});
    assert.deepEqual((await (await get()).json()).regions.map(region => region.id), beforeOutside);
    assert.equal(await evaluate(cdp, 'document.querySelectorAll("[data-selection-active=true]").length'), 1);
    await click('[data-content-node-id][data-display-node-id="grid:overview"]');
    await waitFor(() => sync().length === 2);
    const ids = sync().map(region => region.id);
    const beforeRemoval = messages.length;
    await click('[aria-label="Remove selection"]');
    await waitFor(() => sync().length === 1);
    const removal = messages.slice(beforeRemoval).find(message => message.type === 'selection.delta' && message.removed.length);
    assert.ok(removal); assert.deepEqual(removal.upserted, []);
    assert.ok(ids.includes(removal.removed[0]));
    await click('[aria-label="Remove selection"]');
    await waitFor(() => sync().length === 0);
    assert.deepEqual((await (await get()).json()).regions, []);
    const mouse = (type, p, modifiers = 2) => cdp.send('Input.dispatchMouseEvent', { type, ...p, button: 'left', buttons: type === 'mouseReleased' ? 0 : 1, modifiers, clickCount: 1 });
    const box = id => evaluate(cdp, `(() => { const r = document.querySelector('[data-grid-box="${id}"]').getBoundingClientRect();
      return { left:r.left, top:r.top, right:r.right, bottom:r.bottom }; })()`);
    const a = await box('overview'), b = await box('other');
    const start = { x: a.left - 6, y: a.top - 6 }, full = { x: a.right + 6, y: a.bottom + 6 };
    // Shift no longer owns selection.
    await mouse('mousePressed', start, 8); await mouse('mouseMoved', full, 8); await mouse('mouseReleased', full, 8);
    assert.equal(sync().length, 0); assert.deepEqual(diagramIds, []);
    // A canceled Ctrl gesture leaves both selection and the wire unchanged.
    const beforeCancel = messages.length;
    await mouse('mousePressed', start); await mouse('mouseMoved', full);
    await waitForSelector(cdp, '[data-diagram-selection-preview]');
    assert.equal(messages.slice(beforeCancel).filter(m => m.type === 'selection.delta').length, 0);
    await key('Escape', 'Escape', 27); await mouse('mouseReleased', full);
    await waitFor(async () => !await evaluate(cdp, '!!document.querySelector("[data-selection-preview]")'));
    assert.equal(sync().length, 0); assert.deepEqual(diagramIds, []);
    // Select a partial region first, then replace it with the whole diagram.
    await mouse('mousePressed', points.start); await mouse('mouseMoved', points.end); await mouse('mouseReleased', points.end);
    await waitFor(() => sync().some(region => region.text === expected));
    await key('Escape', 'Escape', 27);
    await waitFor(() => sync().length === 0, { message: 'Escape deselects a completed region' });
    assert.equal(await evaluate(cdp, 'document.querySelectorAll("[data-selection-active=true], .mapping-poc-selection-rect").length'), 0);
    await click('[data-content-node-id][data-display-node-id="grid:overview"]');
    await waitFor(() => sync().length === 1);
    await key('Escape', 'Escape', 27);
    await waitFor(() => sync().length === 0, { message: 'Escape deselects a clicked node region' });
    await click('[data-content-node-id][data-display-node-id="grid:overview"]');
    await waitFor(() => sync().length === 1);
    const firstRegionId = sync()[0].id;
    // Focusing an earlier region makes it the next one dismissed.
    await click('[data-content-node-id][data-display-node-id="grid:other"][data-source-line="3"]');
    await waitFor(() => sync().length === 2);
    const lastRegionId = sync().find(region => region.id !== firstRegionId).id;
    await click(`[data-selection-root="${firstRegionId}"] button[aria-keyshortcuts=A]`);
    await key('Escape', 'Escape', 27);
    await waitFor(() => sync().length === 1);
    assert.equal(sync()[0].id, lastRegionId, 'Escape removes the focused region, preserving the other region');
    await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27, autoRepeat: true });
    await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
    assert.equal(sync().length, 1, 'Holding Escape does not clear additional regions');
    await key('Escape', 'Escape', 27);
    await waitFor(() => sync().length === 0);
    await click('[data-content-node-id][data-display-node-id="grid:overview"]');
    await waitFor(() => sync().length === 1);
    const remainingRegionId = sync()[0].id;
    await click('[data-content-node-id][data-display-node-id="grid:other"][data-source-line="3"]');
    await waitFor(() => sync().length === 2);
    // Starting and canceling placement clears UI focus, but retains selection membership.
    await click('[data-grid-box="other"] .mapping-grid-box-tools button:nth-child(2)');
    await key('Escape', 'Escape', 27);
    assert.equal(sync().length, 2, 'Canceling placement preserves the selected regions');
    await key('Escape', 'Escape', 27);
    await waitFor(() => sync().length === 1, { message: 'Escape deselects one region without UI focus' });
    assert.equal(sync()[0].id, remainingRegionId, 'Escape removes the most recently added region when none is focused');
    await key('Escape', 'Escape', 27);
    await waitFor(() => sync().length === 0, { message: 'Escape deselects regions without UI focus' });
    assert.equal(await evaluate(cdp, 'document.querySelectorAll("[data-selection-active=true], .mapping-poc-selection-rect").length'), 0);
    await mouse('mousePressed', points.start); await mouse('mouseMoved', points.end); await mouse('mouseReleased', points.end);
    await waitFor(() => sync().some(region => region.text === expected));
    const oldIds = sync().map(region => region.id);
    const promotionStart = messages.length;
    await mouse('mousePressed', start); await mouse('mouseMoved', full);
    // Promotion remains sticky when the pointer comes back inside the box.
    const shrunk = { x: a.left + 4, y: a.top + 4 };
    await mouse('mouseMoved', shrunk); await mouse('mouseReleased', shrunk);
    await waitFor(() => { sync(); return diagramIds.includes('grid:overview'); });
    assert.deepEqual(sync(), []);
    const promotion = messages.slice(promotionStart).find(m => m.diagramIds?.includes('grid:overview'));
    assert.deepEqual(promotion.upserted, []); assert.deepEqual(promotion.removed.sort(), oldIds.sort());
    assert.deepEqual((await (await get()).json()).diagramIds, ['grid:overview']);
    assert.ok(attached.context.nodes.some(node => node.id === diagramIds[0]));
    await key('Escape', 'Escape', 27);
    await waitFor(() => { sync(); return !diagramIds.length; });
    assert.deepEqual(sync(), [], 'Deselecting a diagram must not resurrect its old regions');
    // One marquee may include a whole diagram and only part of a second diagram.
    const mixedEnd = { x: b.left + (b.right - b.left) * .45, y: b.bottom + 6 };
    await mouse('mousePressed', start); await mouse('mouseMoved', mixedEnd); await mouse('mouseReleased', mixedEnd);
    await waitFor(() => { const r = sync(); return diagramIds.includes('grid:overview') && r.some(region => region.sourceBoxId === 'other'); });
    assert.equal(sync().length, 1);
    assert.ok(sync()[0].text.includes('Associated Code Entities:'));
    await key('c', 'KeyC', 67);
    await waitFor(async () => await evaluate(cdp, 'navigator.clipboard.readText()') === sync()[0].text);
    assert.equal(await evaluate(cdp, 'document.querySelector("[data-grid-box=overview]").dataset.diagramSelected'), 'true');
    // Whole-diagram gestures use the same membership as regions and the socket snapshot.
    const doubleClickDiagram = async (boxId, toggle) => {
      const point = await evaluate(cdp, `(() => {
        const box = document.querySelector('[data-grid-box="${boxId}"]'), r = box.getBoundingClientRect();
        for (let y = r.top + 3; y < r.bottom; y += 5) for (let x = r.left + 3; x < r.right; x += 5) {
          const target = document.elementFromPoint(x, y);
          if (target?.closest('[data-diagram-canvas]') && !target.closest('[data-content-node-id],button,a,[data-mapping-static-ui],[data-display-node]')) return {x, y};
        }
        throw Error('No exposed diagram background');
      })()`);
      for (const clickCount of [1, 2]) {
        await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...point, button: 'left', buttons: 1, clickCount, modifiers: toggle ? 2 : 0 });
        await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...point, button: 'left', clickCount, modifiers: toggle ? 2 : 0 });
      }
    };
    const otherRegionId = sync()[0].id;
    await doubleClickDiagram('overview', true);
    await waitFor(() => { sync(); return diagramIds.length === 0; });
    assert.equal(sync()[0].id, otherRegionId, 'Toggling a diagram preserves unrelated region identity');
    await doubleClickDiagram('overview', true);
    await waitFor(() => { sync(); return diagramIds.includes('grid:overview'); });
    assert.equal(sync()[0].id, otherRegionId);
    await doubleClickDiagram('overview', false);
    await waitFor(() => sync().length === 0);
    assert.deepEqual(diagramIds, ['grid:overview'], 'Plain double-click replaces the entire mixed selection');
    await click('.mapping-grid-tools button:first-child');
    await waitFor(() => sync().some(region => region.id === otherRegionId));
    assert.deepEqual(diagramIds, ['grid:overview'], 'Undo restores the previous mixed collection');
    await click('.mapping-grid-tools button:nth-child(2)');
    await waitFor(() => sync().length === 0);
    assert.deepEqual(diagramIds, ['grid:overview'], 'Redo restores whole-diagram replacement');
    await doubleClickDiagram('overview', true);
    await waitFor(() => { sync(); return diagramIds.length === 0; });
    assert.deepEqual(sync(), [], 'Deselection must not revive replaced regions');
    await doubleClickDiagram('overview', false);
    await doubleClickDiagram('other', true);
    await waitFor(() => { sync(); return diagramIds.length === 2; });
    await key('Escape', 'Escape', 27);
    await waitFor(() => { sync(); return diagramIds.length === 1; });
    assert.deepEqual(diagramIds, ['grid:overview'], 'Escape removes only the last selected diagram');
    await key('Escape', 'Escape', 27);
    await waitFor(() => { sync(); return diagramIds.length === 0; });
    await mouse('mousePressed', start); await mouse('mouseMoved', mixedEnd); await mouse('mouseReleased', mixedEnd);
    await waitFor(() => { sync(); return diagramIds.length === 1 && regions.size === 1; });
    await key('Escape', 'Escape', 27);
    await waitFor(() => sync().length === 0);
    assert.deepEqual(diagramIds, ['grid:overview'], 'Deselecting a region preserves the selected whole diagram');
    await key('Escape', 'Escape', 27);
    await waitFor(() => { sync(); return diagramIds.length === 0; });
    await mouse('mousePressed', start); await mouse('mouseMoved', mixedEnd); await mouse('mouseReleased', mixedEnd);
    await waitFor(() => { const r = sync(); return diagramIds.includes('grid:overview') && r.some(region => region.sourceBoxId === 'other'); });
    await captureScreenshot(cdp, { output: process.env.LIVE_CANVAS_SELECTION_SCREENSHOT || path.join(root, 'mixed-selection.png') });
    await waitFor(async () => {
      const value = await fetch(`${url}/api/mapping/workspace`).then(r => r.json());
      const workspace = value.workspace ?? value;
      return workspace.documents?.some(doc => doc.canvas.selection.items.some(item => !item.region && item.displayNodeId === 'grid:overview'));
    });
    await cdp.send('Page.reload', { ignoreCache: true });
    await waitFor(() => messages.some(m => m.type === 'canvas.disconnected'));
    await waitForSelector(cdp, '[data-grid-box="overview"]');
    await waitFor(async () => await statusText() === 'No agents connected');
    let refreshed;
    await waitFor(async () => {
      const descriptors = await fetch(`${url}/api/mapping/agent/canvases`).then(r => r.json());
      const matches = descriptors.filter(value => value.stableWorkspaceId === canvas.stableWorkspaceId);
      refreshed = matches.length === 1 && matches[0].canvasId !== canvas.canvasId ? matches[0] : undefined;
      return refreshed?.documents.length;
    });
    assert.equal(refreshed.projectId, canvas.projectId);
    assert.deepEqual(refreshed.documents, canvas.documents);
    assert.equal((await get()).status, 503, 'Old connection must not silently rebind after reload');
    const closed = once(socket, 'close'); socket.close(); await closed;
    await waitFor(async () => (await get()).status === 404);
    // An opener-created tab copies sessionStorage. It must acquire a new stable
    // identity instead of competing with the original tab's runtime ownership.
    await cdp.send('Runtime.evaluate', { expression: 'window.open(location.href, "_blank")', userGesture: true });
    let duplicate;
    await waitFor(async () => {
      duplicate = (await fetch(`${url}/api/mapping/agent/canvases`).then(r => r.json()))
        .find(value => value.stableWorkspaceId !== canvas.stableWorkspaceId && value.documents.length);
      return duplicate;
    });
    assert.ok(duplicate.stableWorkspaceId);
    assert.equal(duplicate.projectId, canvas.projectId);
    console.log('PASS: agent indicator 0 → 1 → 2 → 1 → 0, Ctrl-only mixed selection, sticky diagram promotion, cancellation, double-click replacement/toggling and undo/redo, nodes.list IDs, exact copy payload, multiple regions, removal deltas, conditional GET, reload invalidation, stable tab identity, isolated duplicate identity, disconnect cleanup');
    } catch (error) { console.error('Browser assertion failed:', error); throw error; }
  });
} finally {
  socket?.terminate(); secondSocket?.terminate();
  if (server?.pid) { try { process.kill(-server.pid, 'SIGTERM'); } catch {} }
  await rm(root, { recursive: true, force: true });
}

