// Run after npm run build: node --import tsx tests/browser/mapping/browser-llm-panel-check.mjs
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { canvasSaveFixture } from '../../support/mappingDiagram.ts';
import { revisionFixture } from '../../support/diagramRevisions.ts';
import { singleDiagramScene, projectCanvasSnapshot } from '../../../domain/core/diagrams/projectDiagramCanvas.ts';
import { asciiSha256 } from '../../../domain/core/diagrams/asciiSha256.ts';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'diagram-edit-ui-'));
let server;
try {
  await seedMappingFixture(root, { ascii: 'First\n+-- Existing\n|   `-- Child\n`-- Untouched', nodes: [] });
  const catalogPath = path.join(root, '.diagrams/representations/catalog.json');
  const catalog = JSON.parse(await readFile(catalogPath, 'utf8'));
  const scene = singleDiagramScene('First\n+-- Existing\n|   `-- Child\n`-- Untouched');
  const diagrams = revisionFixture();
  scene.contents = { ...scene.contents,
    overview: diagrams.create({ id: 'overview', revision: 0, ascii: 'First\n+-- Existing\n|   `-- Child\n`-- Untouched', structureKind: 'tree' }).diagram,
    second: diagrams.create({ id: 'second', revision: 0, ascii: 'Second\n`-- Other', structureKind: 'tree' }).diagram };
  scene.root.children.push({ id: 'second', kind: 'diagram', contentId: 'second', position: { column: 35, row: 0 }, collapsed: false });
  const revision = catalog.revisions['revision-overview'];
  revision.content = { kind: 'canvas-history', history: canvasSaveFixture({ name: 'Fixture', scene }).history };
  revision.ascii = projectCanvasSnapshot(scene).ascii; revision.asciiSha256 = asciiSha256(revision.ascii);
  await writeFile(catalogPath, JSON.stringify(catalog));
  const port = await new Promise(resolve => { const s = createServer(); s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => resolve(p)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', 'preview', '--http', '--pi', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { detached: true, env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: path.join(root, '.diagrams'), NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'ignore', 'pipe'] });
  let errors = ''; server.stderr.on('data', c => { errors += c; });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 }).catch(e => { throw Error(`${e}\n${errors}`); });
  await withHeadlessBrowser({ url: `${url}/mapping?diagram=representation-overview`, width: 1800, height: 1100,
    chromePath: process.env.CHROME_PATH, arguments: ['--no-sandbox', '--disable-gpu'] }, async ({ cdp }) => {
    const browserErrors = [];
    await cdp.send('Page.enable'); await cdp.send('Runtime.enable');
    cdp.on('Runtime.exceptionThrown', event => browserErrors.push(event.exceptionDetails));
    await cdp.send('Network.enable');
    const submittedEdits=[];
    cdp.on('Network.requestWillBeSent',event=>{ if(event.request.url.endsWith('/api/mapping/agent/diagram-edits') && event.request.postData) submittedEdits.push(JSON.parse(event.request.postData)); });
    const submittedCreates=[];
    cdp.on('Network.requestWillBeSent',event=>{ if(event.request.url.endsWith('/api/mapping/agent/tools/create-diagram') && event.request.postData) submittedCreates.push(JSON.parse(event.request.postData)); });
    cdp.on('Page.javascriptDialogOpening', () => void cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    const send = cdp.send.bind(cdp);
    cdp.send = async (method, parameters) => {
      let timer;
      try { return await Promise.race([send(method, parameters), new Promise((_, reject) => { timer = setTimeout(() => reject(Error(`CDP timeout: ${method}`)), 15000); })]); }
      finally { clearTimeout(timer); }
    };
    const mouse = async (type, p, clickCount = 1, modifiers = 0) => cdp.send('Input.dispatchMouseEvent', { type, ...p, button: 'left', buttons: type === 'mouseReleased' ? 0 : 1, clickCount, modifiers });
    const click = async (selector, text) => {
      const p = await evaluate(cdp, `(() => { const e=[...document.querySelectorAll(${JSON.stringify(selector)})].find(e=>!${JSON.stringify(text)} || e.textContent.trim()===${JSON.stringify(text)}); if (!e || e.disabled) throw Error('Unavailable: '+${JSON.stringify(text ?? selector)}); const r=e.getBoundingClientRect(); for (const fraction of [0.5, 0.2, 0.8]) { const p={x:r.x+r.width/2,y:r.y+r.height*fraction}; if(e.contains(document.elementFromPoint(p.x,p.y))) return p; } throw Error('Occluded: '+${JSON.stringify(text ?? selector)}); })()`);
      await mouse('mousePressed', p); await mouse('mouseReleased', p);
    };
    const diagramPoint = async id => evaluate(cdp, `(() => {const r=document.querySelector('[data-grid-box="${id}"]').getBoundingClientRect();return{x:r.x+8,y:r.y+8};})()`);
    const select = async id => { const p = await evaluate(cdp, `(() => {const r=document.querySelector('[data-grid-box="${id}"]').getBoundingClientRect();return{x:r.x+2,y:r.bottom-6};})()`); await mouse('mousePressed', p, 2, 2); await mouse('mouseReleased', p, 2, 2); };
    const text = async () => evaluate(cdp, "[...document.querySelectorAll('[data-native-node] .mapping-poc-ascii')].map(el => el.textContent).join('\\n')");
    const key = async (value, modifiers = 0) => {
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key: value, code: ['Escape','End','Enter','Delete'].includes(value) ? value : `Key${value.toUpperCase()}`, modifiers, windowsVirtualKeyCode: ({Escape:27,End:35,Enter:13,Delete:46})[value] ?? value.toUpperCase().charCodeAt(0) });
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: value, modifiers });
    };
    const nodePoint = async label => evaluate(cdp, `(() => { const e=[...document.querySelectorAll('[data-content-node-id][data-display-node-id]')].find(e=>e.textContent.trim()===${JSON.stringify(label)} && e.getBoundingClientRect().width>0); if(!e)throw Error('Missing node'); const r=e.getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);
    const nodeClick = async label => { await waitFor(async()=>await evaluate(cdp,"!document.querySelector('.tl-hit-test-blocker:not(.tl-hit-test-blocker__hidden)')")); const p=await nodePoint(label); await mouse('mousePressed',p,2,2); await mouse('mouseReleased',p,2,2); };
    await waitForSelector(cdp, '[data-grid-box=second]');
    await waitFor(async () => (await diagramPoint('overview')).x > 320);
    const selectedLabels = async () => evaluate(cdp,"[...document.querySelectorAll('[data-native-node] [data-content-node-id].is-selected')].map(e=>e.textContent.trim()).sort()");
    const waitForSelection = async labels => waitFor(async()=>JSON.stringify(await selectedLabels())===JSON.stringify(labels)).catch(async error => {
      console.log('Selection mismatch', { expected: labels, actual: await selectedLabels(), hit: await evaluate(cdp,"[...document.querySelectorAll('[data-native-node] [data-content-node-id]')].map(e=>{const r=e.getBoundingClientRect();return {label:e.textContent,hit:document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)?.outerHTML.slice(0,180)}})") });
      throw error;
    });
    const envelopes = async () => evaluate(cdp, `([...document.querySelectorAll('[data-selection-active=true]')].map(root=>{
      const id=root.dataset.selectionRoot, rect=document.querySelector('[data-native-node="floating:'+id+'"] .retained-selection')?.getBoundingClientRect();
      return {id,width:rect?.width,height:rect?.height};
    }))`);
    await nodeClick('Other');
    await nodeClick('First');
    await waitForSelection(['Child','Existing','First','Other','Untouched']);
    const originalEnvelopes = await envelopes();
    await nodeClick('Existing');
    await waitForSelection(['First','Other','Untouched']);
    assert.deepEqual(await envelopes(), originalEnvelopes, 'Removing an interior subtree preserves envelope identity and dimensions');
    await key('z',2);
    await waitForSelection(['Child','Existing','First','Other','Untouched']);
    await key('y',2);
    await waitForSelection(['First','Other','Untouched']);
    assert.deepEqual(await envelopes(), originalEnvelopes, 'Undo/redo updates membership without fragmenting the rectangle');
    await click('[aria-label="Menu"]');
    await click('button','Save workspace');
    await waitFor(async()=>await evaluate(cdp,"document.querySelector('.mapping-menu-status')?.textContent.includes('Workspace saved')"));
    await click('button','Restore workspace');
    await key('Escape');
    await waitForSelection(['First','Other','Untouched']);
    await waitFor(async()=>JSON.stringify(await envelopes())===JSON.stringify(originalEnvelopes));
    const selectionReloaded = new Promise(resolve => { const off=cdp.on('Page.loadEventFired',()=>{off();resolve();}); });
    await cdp.send('Page.reload',{ignoreCache:true}); await selectionReloaded;
    await waitForSelection(['First','Other','Untouched']);
    await waitFor(async()=>JSON.stringify(await envelopes())===JSON.stringify(originalEnvelopes));
    await key('Escape');
    await waitForSelection(['Other']);
    await key('Escape');
    await waitForSelection([]);
    await key('z',2); await key('z',2);
    await waitForSelection(['First','Other','Untouched']);
    assert.deepEqual(await envelopes(), originalEnvelopes, 'Reload and history synchronize highlights and rectangles without node clicks');
    await captureScreenshot(cdp,{output:process.env.SELECTION_SCREENSHOT_PATH ?? path.join(root,'selection-state.png')});
    console.log('PASS stable selection envelopes, chronological Escape, undo/redo and workspace restore state synchronization');
    await nodeClick('Existing');
    await waitForSelection(['Child','Existing','First','Other','Untouched']);
    await nodeClick('Child');
    await waitForSelection(['Existing','First','Other','Untouched']);
    await nodeClick('Existing');
    await waitForSelection(['First','Other','Untouched']);
    await nodeClick('First');
    await waitForSelection(['Other']);
    await nodeClick('Other');
    await waitFor(async()=>(await selectedLabels()).length===0);
    await select('overview');
    await waitForSelector(cdp,'[data-grid-box=overview][data-diagram-selected=true]');
    await nodeClick('Existing');
    await waitForSelection(['First','Untouched']);
    await nodeClick('First');
    await waitFor(async()=>(await selectedLabels()).length===0);
    console.log('PASS Ctrl-double-click subtree toggle, nested leaf removal, siblings, other diagrams and whole-diagram subtraction');
    await nodeClick('Existing');
    await waitForSelector(cdp,'.retained-selection-controls');
    await click('.retained-selection-controls button','Actions (A)');
    await key('b', 2); await key('l');
    await waitForSelector(cdp,'.llm-panel .prompt-body-text');
    assert.equal(await evaluate(cdp, "document.querySelector('[aria-label=\"LLM mode\"]').value"), 'edit-diagram');
    assert.equal(await evaluate(cdp, "document.querySelectorAll('.prompt-reference').length"), 1);
    const referenceCounts = async () => evaluate(cdp,"[...document.querySelectorAll('.prompt-body .prompt-reference small')].map(e=>e.textContent.match(/(\\d+) nodes?$/)?.[1]).map(Number)");
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[2]');
    await evaluate(cdp,"void (window.originalSelectionChip=document.querySelector('.prompt-body .prompt-reference'))");
    await nodeClick('Child');
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[1]');
    assert.ok(await evaluate(cdp,"window.originalSelectionChip===document.querySelector('.prompt-body .prompt-reference')"), 'Node deselection updates the existing widget in place');
    await key('z',2);
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[2]');
    await key('y',2);
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[1]');
    assert.ok(await evaluate(cdp,"window.originalSelectionChip===document.querySelector('.prompt-body .prompt-reference')"));
    await captureScreenshot(cdp,{output:process.env.REFERENCE_SCREENSHOT_PATH ?? path.join(root,'reference-decrement.png')});
    await nodeClick('Existing');
    await waitFor(async()=>(await referenceCounts()).length===0);
    await key('z',2);
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[1]');
    console.log('PASS one reference widget decrements 2 to 1, follows undo/redo, disappears on empty selection and restores once');
    await click('[aria-label="Close Workspace tools"]');
    await nodeClick('Other');
    // Reopen the existing edit; L deliberately starts a fresh edit for the current selection.
    await key('b', 2); await key('b');
    assert.equal(await evaluate(cdp, "document.querySelectorAll('.prompt-reference').length"), 2);
    console.log('PASS automatic references from subsequent Ctrl-double-click selections');
    await click('.prompt-body-text'); await cdp.send('Input.insertText', { text: 'Revise branch' });
    await click('.llm-panel button[type=submit]');
    await waitForSelector(cdp,'[data-edit-status=completed]',{timeoutMs:15000});
    assert.ok((await text()).includes('Existing [edited: Revise branch'));
    assert.ok((await text()).includes('Untouched'));
    assert.equal(submittedEdits.length,1);
    assert.deepEqual(submittedEdits[0].references.map(reference=>reference.nodeIds.length),[1,1], 'Submitted references contain current selections without historical duplicates');
    console.log('PASS subtree update with the current reference node counts');
    await cdp.send('Browser.grantPermissions', { origin: url, permissions: ['clipboardReadWrite', 'clipboardSanitizedWrite'] });
    const runtimeId = await evaluate(cdp, "document.querySelector('[aria-label=\"Copy agent session ID\"]').title");
    assert.ok(runtimeId.startsWith('fake-agent-'));
    await click('[aria-label="Copy agent session ID"]');
    await waitFor(async()=>await evaluate(cdp, "document.querySelector('[aria-label=\"Copy agent session ID\"]').textContent==='Copied'"));
    assert.equal(await evaluate(cdp, 'navigator.clipboard.readText()'), runtimeId);
    console.log('PASS copy actual agent session ID to clipboard');
    await click('[aria-label="Close Workspace tools"]');
    await key('z',2);
    await waitFor(async()=>!(await text()).includes('[edited:'));
    console.log('PASS subtree undo');
    await key('Escape'); await key('Escape');
    await nodeClick('Existing');
    await key('b', 2); await key('l');
    // Switch mode with real keyboard input.
    await click('[aria-label="LLM mode"]');
    await key('End'); await key('Enter');
    await waitFor(async()=>await evaluate(cdp,"document.querySelector('[aria-label=\"LLM mode\"]').value==='extend-diagram'"));
    await waitForSelector(cdp,'.llm-origin');
    const markerColor = await evaluate(cdp,"getComputedStyle(document.querySelector('.llm-origin')).borderTopColor");
    const [red, green, blue] = markerColor.match(/\d+/g).map(Number);
    assert.ok(green > red && green > blue, 'Extend marker uses the theme’s green accent');
    await waitFor(async()=>await evaluate(cdp,"document.querySelector('.llm-origin').getBoundingClientRect().right<document.querySelector('.window-panel').getBoundingClientRect().left"));
    const sourceSelection = await evaluate(cdp,"document.querySelector('[data-selection-active=true]').dataset.selectionRoot");
    const selectionVisible = async () => evaluate(cdp,"[...document.querySelectorAll('.retained-selection')].some(e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0})");
    assert.ok(await selectionVisible(), 'Source rectangle remains visible with LLM panel open');
    await click('.selection-root-join.llm-origin');
    await cdp.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:1050,y:600,buttons:0});
    await waitForSelector(cdp,'.llm-extension-edge[data-placing=true]');
    const firstEdge=await evaluate(cdp,"document.querySelector('.llm-extension-edge path').getAttribute('d')");
    await cdp.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:1100,y:650,buttons:0});
    await waitFor(async()=>await evaluate(cdp,"document.querySelector('.llm-extension-edge path').getAttribute('d')")!==firstEdge);
    assert.ok(await selectionVisible());
    await key('Escape');
    await waitFor(async () => await evaluate(cdp,"document.querySelectorAll('.llm-extension-edge[data-placing=true]').length") === 0);
    assert.ok(await selectionVisible(), 'Escape cancels placement without removing the source selection');
    await click('.selection-root-join.llm-origin');
    // An occupied drop keeps placement active and leaves the original selection untouched.
    const occupied=await nodePoint('Existing');
    await mouse('mousePressed',occupied); await mouse('mouseReleased',occupied);
    await cdp.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:1050,y:600,buttons:0});
    await waitForSelector(cdp,'.llm-extension-edge[data-placing=true]');
    await captureScreenshot(cdp,{output:process.env.UI_SCREENSHOT_PATH ? process.env.UI_SCREENSHOT_PATH.replace(/\.png$/, '-placing.png') : path.join(root,'placing.png')});
    await mouse('mousePressed',{x:1050,y:600}); await mouse('mouseReleased',{x:1050,y:600});
    await waitFor(async()=>await evaluate(cdp,"document.querySelector('.llm-mode').textContent.includes('New origin:')"));
    assert.equal(await evaluate(cdp,"document.querySelector('[data-selection-active=true]').dataset.selectionRoot"),sourceSelection);
    assert.ok(await selectionVisible(), 'Second click places the origin and preserves the source rectangle');
    await waitFor(async () => await evaluate(cdp,"document.querySelectorAll('.llm-extension-edge[data-placing=true]').length") === 0);
    const blankPrompt = await evaluate(cdp,"(()=>{const r=document.querySelector('.prompt-body').getBoundingClientRect(); const p={x:r.x+r.width/2,y:r.bottom-24}; return {...p,hit:document.elementFromPoint(p.x,p.y)?.className};})()");
    assert.equal(blankPrompt.hit,'prompt-body', 'Exercise blank prompt space rather than targeting a textarea');
    await mouse('mousePressed',{x:blankPrompt.x,y:blankPrompt.y}); await mouse('mouseReleased',{x:blankPrompt.x,y:blankPrompt.y});
    assert.ok(await evaluate(cdp,"document.activeElement?.matches('.prompt-body-text[data-last=true]')"), 'Clicking blank prompt space after placing an extension focuses text input');
    await cdp.send('Input.insertText',{text:'Explain retry'});
    assert.equal(await evaluate(cdp,"document.querySelector('.prompt-body-text[data-last=true]').value"),'Explain retry');
    console.log('PASS typing in blank prompt space immediately after extension placement');
    const savedOrigin=await evaluate(cdp,"document.querySelector('.llm-mode').textContent");
    await click('[aria-label="Move new diagram origin"]');
    await cdp.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:1100,y:650,buttons:0});
    await waitForSelector(cdp,'.llm-extension-edge[data-placing=true]');
    await key('Escape');
    assert.equal(await evaluate(cdp,"document.querySelector('.llm-mode').textContent"),savedOrigin, 'Cancel reposition retains the previously placed origin');
    assert.ok(await selectionVisible());
    console.log('PASS tiny-circle pick, edge follows cursor without holding, cancel, occupied rejection, click placement and reposition cancel');
    await click('.llm-panel button[type=submit]');
    await waitForSelector(cdp,'[data-edit-status=completed]',{timeoutMs:15000});
    await waitFor(async()=>(await text()).includes('[created: [ref 1]Explain retry'));
    await waitForSelector(cdp,'[data-connection-id]');
    assert.equal(await evaluate(cdp,"document.querySelectorAll('[data-connection-id]').length"),2);
    await captureScreenshot(cdp,{output:process.env.UI_SCREENSHOT_PATH ? process.env.UI_SCREENSHOT_PATH.replace(/\.png$/, '-extension.png') : path.join(root,'extension.png')});
    assert.ok(await selectionVisible(), 'Source rectangle remains after extension');
    console.log('PASS extension creation and edge, retained source rectangle');
    await click('[aria-label="Close Workspace tools"]');
    await key('z',2);
    await waitFor(async()=>!(await text()).includes('[created:'));
    assert.equal(await evaluate(cdp,"document.querySelectorAll('[data-connection-id]').length"),0);
    await key('y',2);
    await waitFor(async()=>(await text()).includes('[created:'));
    console.log('PASS extension atomic undo/redo');
    await click('.workspace-tools-open');
    await waitForSelector(cdp,'[aria-label="Search diagram text"]');
    await click('[aria-label="Search diagram text"]'); await cdp.send('Input.insertText',{text:'Untouched'});
    await waitForSelector(cdp,'[data-search-result-line]');
    await click('.window-panel-tabs [role=tab]','LLM');
    await click('.window-panel-tabs [role=tab]','Search');
    assert.equal(await evaluate(cdp,"document.querySelector('[aria-label=\"Search diagram text\"]').value"),'Untouched');
    const aligned=await evaluate(cdp,"Math.abs(document.querySelector('.window-panel').getBoundingClientRect().top-document.querySelector('.mapping-floating-pane').getBoundingClientRect().top)<2");
    assert.ok(aligned);
    assert.ok(await evaluate(cdp,"innerWidth-document.querySelector('.window-panel').getBoundingClientRect().right<25"), 'Shared tools panel sits at the right edge');
    console.log('PASS shared tabs, preserved search, alignment');
    await click('[aria-label="Close Workspace tools"]');
    await click('[role=tab]','Canvas');
    assert.ok(await evaluate(cdp,"!!document.querySelector('.mapping-canvas-actions button')"));
    assert.equal(await evaluate(cdp,"document.querySelectorAll('[aria-label=\"LLM sessions\"]').length"),0);
    console.log('PASS Canvas actions replace Explorer LLM sessions');
    await key('Escape'); await key('Escape');
    await select('second');
    await nodeClick('Existing');
    assert.equal(await evaluate(cdp,"document.querySelectorAll('.mapping-diagram-selection-actions').length"),0);
    await key('b', 2); await key('l');
    assert.ok(await evaluate(cdp,"document.querySelectorAll('.prompt-reference').length>=2"));
    console.log('PASS mixed whole-diagram and Ctrl-double-click node references');
    const loaded = new Promise(resolve => { const off = cdp.on('Page.loadEventFired', () => { off(); resolve(); }); });
    await cdp.send('Page.reload',{ignoreCache:true}); await loaded;
    await waitForSelector(cdp,'[data-grid-box=second]');
    await waitFor(async()=>(await text()).includes('[created:'));
    await waitForSelector(cdp,'[data-connection-id]');
    console.log('PASS persisted extension survives reload');
    for(let i=0;i<10;i++) await key('Escape');
    await click('[role=tab]','Diagrams');
    await key('b', 2); await key('l');
    await waitForSelector(cdp,'.llm-panel .prompt-body-text');
    assert.ok(await evaluate(cdp,"[...document.querySelectorAll('.window-panel-tabs [role=tab]')].some(e=>e.textContent==='LLM' && e.getAttribute('aria-selected')==='true')"));
    assert.equal(await evaluate(cdp,"document.querySelector('[aria-label=\"LLM mode\"]').value"),'create-diagram');
    assert.equal(await evaluate(cdp,"document.querySelectorAll('.prompt-reference').length"),0);
    await click('.prompt-body-text'); await cdp.send('Input.insertText',{text:'Independent diagram'});
    await key('b', 2); await key('l');
    assert.equal(await evaluate(cdp,"document.querySelector('.prompt-body-text').value"),'Independent diagram', 'Panel shortcut does not create a session while typing');
    await click('[aria-label="Close Workspace tools"]');
    await click('[role=tab]','Diagrams');
    await key('b', 2); await key('l');
    await waitForSelector(cdp,'.llm-panel .prompt-body-text');
    assert.equal(await evaluate(cdp,"document.querySelector('.prompt-body-text').value"),'Independent diagram');
    console.log('PASS L opens the LLM tool without selection, preserves drafts, and ignores text fields');
    await click('.llm-panel button[type=submit]');
    await waitForSelector(cdp,'[data-edit-status=completed]',{timeoutMs:15000});
    await waitFor(async()=>(await text()).includes('[created: Independent diagram]'));
    console.log('PASS create without selection');
    const firstCreate = submittedCreates.at(-1);
    assert.ok(firstCreate.llmSessionId);
    assert.equal(firstCreate.agentContext, undefined, 'A new panel starts without another panel’s history');
    const firstCreateId = await evaluate(cdp, "document.querySelector('[aria-label=\"Copy agent session ID\"]').title");
    await click('[aria-label="Close Workspace tools"]');
    await key('b', 2); await key('b');
    await click('.prompt-body-text'); await key('a', 2); await cdp.send('Input.insertText', { text: 'Continue our previous discussion' });
    await click('.llm-panel button[type=submit]');
    await waitForSelector(cdp,'[data-edit-status=completed]',{timeoutMs:15000});
    await waitFor(async()=>(await text()).includes('[created: Continue our previous discussion]'));
    const followup = submittedCreates.at(-1);
    assert.equal(followup.llmSessionId, firstCreate.llmSessionId);
    assert.equal(followup.agentContext.source.sourceSessionId, firstCreate.llmSessionId);
    assert.equal(followup.agentContext.messages[0].content[0].text, 'Independent diagram');
    assert.equal(followup.agentContext.messages.length, 2);
    assert.notEqual(await evaluate(cdp, "document.querySelector('[aria-label=\"Copy agent session ID\"]').title"), firstCreateId);
    console.log('PASS follow-up reuses panel context after reopening and exposes its new runtime ID');
    await click('[aria-label="Close Workspace tools"]');
    await click('[title="Reset zoom and center diagram"]');
    await waitFor(async()=>await evaluate(cdp,"!document.querySelector('.tl-hit-test-blocker:not(.tl-hit-test-blocker__hidden)')"));
    const ids=await evaluate(cdp,"[...document.querySelectorAll('.mapping-grid-box:not(.is-container)')].map(e=>e.dataset.gridBox)");
    await click('[role=tab]','Diagrams');
    for(const id of ids) {
      await click(`[data-explorer-box="${id}"]`);
      await waitFor(async()=>await evaluate(cdp,`(()=>{const r=document.querySelector('[data-grid-box="${id}"]').getBoundingClientRect(); const v=document.querySelector('[data-diagram-canvas]').getBoundingClientRect(); return r.width>0 && Math.abs(r.x+r.width/2-(v.x+v.width/2+170))<3 && !document.querySelector('.tl-hit-test-blocker:not(.tl-hit-test-blocker__hidden)');})()`));
      await click('.diagram-canvas__controls [aria-keyshortcuts="Escape"]');
      await select(id);
      await waitForSelector(cdp, `[data-grid-box="${id}"][data-diagram-selected=true]`);
      await key('Delete');
      await waitFor(async()=>!await evaluate(cdp,`!!document.querySelector('[data-grid-box="${id}"]')`));
    }
    await waitForSelector(cdp,'.mapping-empty-canvas');
    await key('b', 2); await key('l');
    await click('.prompt-body-text'); await key('a', 2); await cdp.send('Input.insertText',{text:'From empty canvas'});
    await click('.llm-panel button[type=submit]');
    await waitForSelector(cdp,'[data-edit-status=completed]',{timeoutMs:15000});
    await waitFor(async()=>(await text()).includes('[created: From empty canvas]'));
    await waitFor(async()=>await evaluate(cdp,`(()=>{ const e=[...document.querySelectorAll('[data-native-node] .mapping-poc-ascii')].find(e=>e.textContent.includes('[created: From empty canvas]'));
      const r=e?.getBoundingClientRect(), panel=document.querySelector('.window-panel').getBoundingClientRect();
      return r && r.width>0 && r.right<panel.left && r.left>document.querySelector('.mapping-floating-pane').getBoundingClientRect().right && r.top>0 && r.bottom<innerHeight; })()`)).catch(async error => {
      await captureScreenshot(cdp,{output:'/tmp/llm-visibility-failure.png'});
      console.log('visibility',await evaluate(cdp,"[...document.querySelectorAll('[data-native-node] .mapping-poc-ascii')].map(e=>({text:e.textContent,rect:e.getBoundingClientRect().toJSON()}))")); throw error;
    });
    await captureScreenshot(cdp,{output:process.env.UI_SCREENSHOT_PATH ?? path.join(root,'create.png')});
    console.log('PASS create on empty canvas');
    await click('[aria-label="Close Workspace tools"]');
    await key('z',2); await waitForSelector(cdp,'.mapping-empty-canvas');
    console.log('PASS empty-canvas creation undo');
    assert.deepEqual(browserErrors, [], 'No browser runtime exceptions');
  });
} finally {
  if (server?.pid) { try { process.kill(-server.pid,'SIGTERM'); } catch {} }
  await rm(root,{recursive:true,force:true});
}

